        this.blockMarkReadingRestoreOwned(
          checkbox,
          "aria-label",
          "aria-label",
          record.appliedAria,
          record.originalAria,
        );
        this.blockMarkReadingRestoreOwned(
          checkbox,
          "data-tooltip-position",
          "data-tooltip-position",
          record.appliedPosition,
          record.originalPosition,
        );
