        name === "hmd-codeblock" ||
        name.indexOf("inline-code") !== -1 ||
        name === "fencedcode" ||
        name === "codeblock" ||
        name === "codetext" ||
        name === "codemark" ||
        name === "codeinfo" ||
        name === "inlinecode"
