          // Date-mark calendar labels roll over at local midnight.
          try {
            this.refreshDateMarksForRollover(new Date());
          } catch (error) {
            // Best-effort refresh only.
          }
          // In Progress marks follow the daily note at local
          // midnight.
          try {
            this.refreshProgressMarksForRollover(new Date());
          } catch (error) {
            // Best-effort refresh only.
          }
          // Unblocked hand-off glyphs follow the daily note at local
          // midnight.
          try {
            this.refreshUnblockedGlyphForRollover(new Date());
          } catch (error) {
            // Best-effort refresh only.
          }
