// Shared bank data service: cached `bob bank list|report` reads, filtered
// invalidation, subscribe/teardown. Bob owns every total; this fragment
// only moves JSON. A late response never overwrites a newer generation.

class BobLedgerToolsBankDataMixin {
  bankTimerApi() {
    if (this.bankTimers && typeof this.bankTimers === "object") {
      return this.bankTimers;
    }
    return typeof window !== "undefined" && window ? window : globalThis;
  }

  bankSetTimeout(callback, delay) {
    const timers = this.bankTimerApi();
    const schedule = timers && typeof timers.setTimeout === "function"
      ? timers.setTimeout.bind(timers)
      : setTimeout;
    return schedule(callback, delay);
  }

  bankClearTimeout(timer) {
    if (timer === null || timer === undefined) {
      return;
    }
    const timers = this.bankTimerApi();
    const clear = timers && typeof timers.clearTimeout === "function"
      ? timers.clearTimeout.bind(timers)
      : clearTimeout;
    clear(timer);
  }

  bankCacheStore() {
    if (!(this.bankCache instanceof Map)) {
      this.bankCache = new Map();
    }
    return this.bankCache;
  }

  bankMountsStore() {
    if (!(this.bankMounts instanceof Set)) {
      this.bankMounts = new Set();
    }
    return this.bankMounts;
  }

  bankFlightsStore() {
    if (!(this.bankFlights instanceof Map)) {
      this.bankFlights = new Map();
    }
    return this.bankFlights;
  }

  bankPendingStore() {
    if (!(this.bankPendingFetches instanceof Map)) {
      this.bankPendingFetches = new Map();
    }
    return this.bankPendingFetches;
  }

  bankLatestStore() {
    if (!(this.bankLatestGeneration instanceof Map)) {
      this.bankLatestGeneration = new Map();
    }
    return this.bankLatestGeneration;
  }

  bankFetchErrorsStore() {
    if (!(this.bankFetchErrors instanceof Map)) this.bankFetchErrors = new Map();
    return this.bankFetchErrors;
  }

  bankCacheGet(key) {
    const store = this.bankCacheStore();
    const entry = store.get(key);
    if (!entry) {
      return null;
    }
    store.delete(key);
    store.set(key, entry);
    return entry;
  }

  bankCacheSet(key, report, generation) {
    const store = this.bankCacheStore();
    const existing = store.get(key);
    if (existing && Number(existing.generation) > Number(generation)) {
      return existing;
    }
    if (store.has(key)) {
      store.delete(key);
    }
    const entry = { report, fetchedAt: Date.now(), generation: Number(generation) || 0 };
    store.set(key, entry);
    while (store.size > BANK_CACHE_SIZE) {
      const oldest = store.keys().next();
      if (oldest.done) {
        break;
      }
      store.delete(oldest.value);
    }
    return entry;
  }

  bankLastGoodReport(key) {
    const cached = this.bankCacheGet(key);
    return cached ? cached.report : null;
  }

  bankUnloadedResult(key) {
    return {
      report: null,
      stale: false,
      key,
      error: { code: "unloaded", message: "Bank data has unloaded.", detail: "" },
    };
  }

  bankSpawnFetch(args, options = {}) {
    const command = Array.isArray(args) && args[1] === "report" ? "report" : "list";
    const decoder = command === "report" ? bankDecodeReport : bankDecodeList;
    return bobSpawnJson(args, decoder, {
      ...options,
      commandLabel: command === "report" ? "bob bank report" : "bob bank list",
      resolveBobPath: () =>
        typeof this.apiStatsBobPath === "function"
          ? this.apiStatsBobPath()
          : { path: "bob", source: "path" },
      getVaultPath: () =>
        typeof this.statsVaultBasePath === "function"
          ? this.statsVaultBasePath()
          : null,
      timeout: BOB_SPAWN_TIMEOUT_MS,
      maxBuffer: BOB_SPAWN_MAX_BUFFER,
      firstLine: statsFirstLine,
    });
  }

  bankFetchesFor(spec = {}) {
    const opts = bankJsonObject(spec) ? spec : {};
    if (Array.isArray(opts.fetches)) {
      return opts.fetches.filter((entry) => bankJsonObject(entry));
    }
    const fetches = [];
    if (opts.list === true || opts.command === "list") {
      fetches.push({ command: "list", all: opts.all === true, month: opts.month });
    }
    if (
      opts.command === "report" || opts.report === true ||
      opts.month || opts.date || opts.day || opts.week || opts.year || opts.period
    ) {
      fetches.push({
        command: "report",
        month: opts.month,
        date: opts.date,
        day: opts.day,
        week: opts.week,
        year: opts.year,
        period: opts.period,
        summary: opts.summary === true,
      });
    }
    if (fetches.length === 0 && (opts.month || opts.date || opts.day)) {
      fetches.push({ command: "report", month: opts.month, date: opts.date, day: opts.day });
    }
    if (fetches.length === 0) {
      fetches.push({ command: "list" });
    }
    return fetches;
  }

  apiBankFetch(options = {}) {
    const opts = bankJsonObject(options) ? options : {};
    const force = opts.force === true;
    const args = bankBuildArgs(opts);
    const key = bankCacheKey(args);
    if (this.bankDataActive === false) {
      return Promise.resolve(this.bankUnloadedResult(key));
    }
    const generation = Math.max(
      this.bankVaultGeneration || 0,
      Number.isInteger(opts.requiredGeneration) ? opts.requiredGeneration : 0,
    );
    this.bankLatestStore().set(key, Math.max(this.bankLatestStore().get(key) || 0, generation));
    const cached = this.bankCacheGet(key);
    const flight = this.bankFlightsStore().get(key);
    if (flight) {
      if (!force && generation <= flight.generation && cached) {
        return Promise.resolve({
          report: cached.report,
          stale: true,
          error: null,
          key,
          generation: cached.generation,
        });
      }
      if (!force && generation <= flight.generation) {
        return flight.promise;
      }
      return this.bankQueueFetch(key, args, opts, generation, true);
    }
    if (cached && !force && generation <= (cached.generation || 0)) {
      this.bankStartFetch(args, key, { ...opts, force: true }, generation);
      return Promise.resolve({
        report: cached.report,
        stale: true,
        error: null,
        key,
        generation: cached.generation,
      });
    }
    return this.bankStartFetch(args, key, opts, generation).promise;
  }

  apiBankRefresh(options = {}) {
    return this.apiBankFetch({ ...(bankJsonObject(options) ? options : {}), force: true });
  }

  bankQueueFetch(key, args, opts, generation, waitForResult) {
    const pendingStore = this.bankPendingStore();
    let resolve = null;
    const result = waitForResult
      ? new Promise((done) => { resolve = done; })
      : null;
    let pending = pendingStore.get(key);
    if (!pending) {
      pending = { key, args, opts: { ...opts, force: true }, generation, waiters: [] };
      pendingStore.set(key, pending);
    } else {
      pending.opts = { ...pending.opts, ...opts, force: true };
      pending.generation = Math.max(pending.generation, generation);
      pending.args = args;
    }
    this.bankLatestStore().set(key, Math.max(this.bankLatestStore().get(key) || 0, generation));
    if (resolve) {
      pending.waiters.push(resolve);
    }
    return result || Promise.resolve({ report: null, stale: false, error: null, queued: true, key });
  }

  bankStartFetch(args, key, opts, requiredGeneration) {
    const epoch = this.bankDataEpoch || 0;
    const generation = Math.max(
      this.bankVaultGeneration || 0,
      Number.isInteger(requiredGeneration) ? requiredGeneration : 0,
    );
    this.bankLatestStore().set(key, Math.max(this.bankLatestStore().get(key) || 0, generation));
    const flight = { key, args, opts: { ...opts }, generation, epoch, promise: null };
    const run = async () => {
      if (this.bankDataActive === false || this.bankDataEpoch !== epoch) {
        return this.bankUnloadedResult(key);
      }
      try {
        const result = await this.bankSpawnFetch(args, opts);
        if (this.bankDataActive === false || this.bankDataEpoch !== epoch) {
          return this.bankUnloadedResult(key);
        }
        const latest = this.bankLatestStore().get(key) || 0;
        const superseded = generation < latest;
        if (result && result.ok) {
          this.bankCacheSet(key, result.report, generation);
          this.bankFetchErrorsStore().delete(key);
          return {
            report: result.report,
            stale: superseded,
            error: null,
            key,
            generation,
          };
        }
        const staleReport = this.bankLastGoodReport(key);
        const fetchError = result || { code: "failed", message: "bob bank failed.", detail: "" };
        this.bankFetchErrorsStore().set(key, fetchError);
        return {
          report: staleReport,
          stale: Boolean(staleReport),
          error: fetchError,
          key,
          generation,
        };
      } catch (error) {
        const staleReport = this.bankLastGoodReport(key);
        const fetchError = {
          ok: false,
          code: "failed",
          message: error && error.message ? String(error.message) : "bob bank failed.",
          detail: "",
        };
        this.bankFetchErrorsStore().set(key, fetchError);
        return {
          report: staleReport,
          stale: Boolean(staleReport),
          error: fetchError,
          key,
          generation,
        };
      }
    };
    flight.promise = Promise.resolve()
      .then(run)
      .then((outcome) => {
        if (this.bankDataActive !== false && this.bankDataEpoch === epoch) {
          this.bankDeliverFetchResult(flight, outcome);
        }
        return outcome;
      })
      .finally(() => {
        if (this.bankFlightsStore().get(key) === flight) {
          this.bankFlightsStore().delete(key);
          this.bankStartNextFetch(key, epoch);
        }
      });
    this.bankFlightsStore().set(key, flight);
    return flight;
  }

  bankStartNextFetch(key, epoch = this.bankDataEpoch || 0) {
    if (this.bankDataActive === false || this.bankDataEpoch !== epoch) {
      return;
    }
    const pending = this.bankPendingStore().get(key);
    if (!pending) {
      return;
    }
    this.bankPendingStore().delete(key);
    const next = this.bankStartFetch(pending.args, key, pending.opts, pending.generation);
    for (const waiter of pending.waiters) {
      next.promise.then(waiter, () => waiter(this.bankUnloadedResult(key)));
    }
  }

  bankDeliverFetchResult(flight, result) {
    if (!flight || !result || this.bankDataActive === false) {
      return;
    }
    for (const mount of this.bankMountsStore()) {
      if (!mount || mount.unloaded === true) {
        continue;
      }
      const keys = (mount.keys || []).map((entry) => entry.key);
      if (!keys.includes(flight.key)) {
        continue;
      }
      try {
        mount.subscriber(this.bankMountState(mount));
      } catch (error) {
        // A mounted renderer cannot break shared bank refresh.
      }
    }
  }

  bankMountState(mount) {
    const results = {};
    let stale = false;
    let error = null;
    for (const entry of mount.keys || []) {
      const cached = this.bankCacheGet(entry.key);
      const flight = this.bankFlightsStore().get(entry.key);
      results[entry.key] = {
        report: cached ? cached.report : null,
        stale: Boolean(
          cached && (
            (cached.generation || 0) < (this.bankVaultGeneration || 0) ||
            (this.bankLatestStore().get(entry.key) || 0) > (cached.generation || 0)
          ),
        ),
        error: this.bankFetchErrorsStore().get(entry.key) || null,
        refreshing: Boolean(flight),
        args: entry.args,
      };
      if (results[entry.key].stale) {
        stale = true;
      }
    }
    return {
      results,
      stale,
      error,
      generation: this.bankVaultGeneration || 0,
      today: this.bankLocalDay || bankLocalDate(),
    };
  }

  apiBankSubscribe(spec, subscriber) {
    if (typeof subscriber !== "function" || this.bankDataActive === false) {
      return () => {};
    }
    const fetches = this.bankFetchesFor(spec);
    const keys = fetches.map((options) => {
      const args = bankBuildArgs(options);
      return { options, args, key: bankCacheKey(args) };
    });
    const mount = { spec, subscriber, keys, unloaded: false };
    this.bankMountsStore().add(mount);
    try {
      subscriber(this.bankMountState(mount));
    } catch (error) {
      // A subscriber may mount before its renderer is ready.
    }
    for (const entry of keys) {
      void this.apiBankFetch(entry.options);
    }
    return () => {
      mount.unloaded = true;
      this.bankMountsStore().delete(mount);
    };
  }

  apiBankInvalidate(reason = "manual") {
    if (this.bankDataActive === false) {
      return;
    }
    this.bankVaultGeneration = (this.bankVaultGeneration || 0) + 1;
    this.bankInvalidationReason = String(reason || "vault");
    for (const mount of this.bankMountsStore()) {
      if (!mount || mount.unloaded === true) continue;
      try { mount.subscriber(this.bankMountState(mount)); } catch (error) {}
    }
    this.bankScheduleRevalidate(reason);
  }

  apiBankMonthPaths() {
    try {
      const files = this.app && this.app.vault && typeof this.app.vault.getMarkdownFiles === "function"
        ? this.app.vault.getMarkdownFiles()
        : [];
      return bankDiscoverMonthPaths(files);
    } catch (error) {
      return [];
    }
  }

  bankApi() {
    return Object.freeze({
      version: 2,
      fetch: (options) => this.apiBankFetch(options),
      refresh: (options) => this.apiBankRefresh(options),
      subscribe: (spec, subscriber) => this.apiBankSubscribe(spec, subscriber),
      invalidate: (reason) => this.apiBankInvalidate(reason),
      monthPaths: () => this.apiBankMonthPaths(),
      locateHeading: (source, month, date) => bankLocateDayHeading(source, month, date),
      recognize: (path, source, line) => bankRecognizeRow(path, source, line),
      ...(typeof this.apiBankActions === "function" ? this.apiBankActions() : {}),
    });
  }

  bankScheduleRevalidate(reason = "vault") {
    void reason;
    if (this.bankDataActive === false || this.bankMountsStore().size === 0) {
      return;
    }
    this.bankClearTimeout(this.bankRevalidateTimer);
    this.bankRevalidateTimer = this.bankSetTimeout(() => {
      this.bankRevalidateTimer = null;
      this.bankRevalidateMounts();
    }, BANK_REVALIDATE_DEBOUNCE_MS);
  }

  bankRevalidateMounts() {
    if (this.bankDataActive === false) {
      return;
    }
    const generation = this.bankVaultGeneration || 0;
    const seen = new Set();
    for (const mount of this.bankMountsStore()) {
      if (!mount || mount.unloaded === true) {
        continue;
      }
      for (const entry of mount.keys || []) {
        if (seen.has(entry.key)) {
          continue;
        }
        seen.add(entry.key);
        void this.apiBankFetch({
          ...entry.options,
          force: true,
          requiredGeneration: generation,
        });
      }
    }
  }

  bankHandleFileEvent(file, oldPath) {
    const current = bankRelevantPath(file);
    const previous = oldPath ? bankRelevantPath(oldPath) : false;
    if (!current && !previous) {
      return;
    }
    this.apiBankInvalidate("vault");
  }

  bankRefreshRollover(now = new Date()) {
    const day = bankLocalDate(now);
    if (!day) {
      return false;
    }
    if (this.bankLocalDay === null || this.bankLocalDay === undefined) {
      this.bankLocalDay = day;
      return false;
    }
    if (this.bankLocalDay === day) {
      return false;
    }
    this.bankLocalDay = day;
    this.apiBankInvalidate("local-date-rollover");
    return true;
  }

  setupBankData() {
    this.bankDataActive = true;
    this.bankDataEpoch = (this.bankDataEpoch || 0) + 1;
    this.bankVaultGeneration = 0;
    this.bankCache = new Map();
    this.bankMounts = new Set();
    this.bankFlights = new Map();
    this.bankPendingFetches = new Map();
    this.bankLatestGeneration = new Map();
    this.bankFetchErrors = new Map();
    this.bankRevalidateTimer = null;
    this.bankRolloverTimer = null;
    this.bankLocalDay = bankLocalDate();
    try {
      const metadataCache = this.app && this.app.metadataCache;
      if (metadataCache && typeof metadataCache.on === "function") {
        this.registerEvent(metadataCache.on("changed", (file) => this.bankHandleFileEvent(file)));
      }
    } catch (error) {
      // Metadata-cache revalidation is best-effort.
    }
    try {
      const vault = this.app && this.app.vault;
      if (vault && typeof vault.on === "function") {
        for (const event of ["create", "modify", "delete", "rename"]) {
          this.registerEvent(vault.on(event, (file, oldPath) => this.bankHandleFileEvent(file, oldPath)));
        }
      }
    } catch (error) {
      // Vault revalidation is best-effort.
    }
    try {
      const workspace = this.app && this.app.workspace;
      if (workspace && typeof workspace.on === "function") {
        this.registerEvent(workspace.on("active-leaf-change", () => this.bankScheduleRevalidate("active-leaf")));
        this.registerEvent(workspace.on("file-open", () => this.bankScheduleRevalidate("file-open")));
      }
    } catch (error) {
      // Focused-leaf revalidation is best-effort.
    }
    try {
      if (typeof this.registerDomEvent === "function" && typeof window !== "undefined" && window) {
        this.registerDomEvent(window, "focus", () => this.bankScheduleRevalidate("window-focus"));
        if (typeof document !== "undefined" && document) {
          this.registerDomEvent(document, "visibilitychange", () => {
            if (document.visibilityState === "visible") {
              this.bankScheduleRevalidate("document-visible");
            }
          });
        }
      }
    } catch (error) {
      // Focus and visibility are best-effort.
    }
    try {
      const timers = this.bankTimerApi();
      const hasTimerHost = Boolean(
        (this.bankTimers && typeof this.bankTimers === "object") ||
        (typeof window !== "undefined" && window),
      );
      const setIntervalFn = hasTimerHost && timers && typeof timers.setInterval === "function"
        ? timers.setInterval.bind(timers)
        : null;
      if (setIntervalFn) {
        this.bankRolloverTimer = setIntervalFn(() => {
          try {
            this.bankRefreshRollover(new Date());
          } catch (error) {
            // Rollover is best-effort.
          }
        }, BANK_ROLLOVER_INTERVAL_MS);
        if (typeof this.registerInterval === "function") {
          this.registerInterval(this.bankRolloverTimer);
        }
      }
    } catch (error) {
      this.bankRolloverTimer = null;
    }
  }

  teardownBankData() {
    this.bankDataActive = false;
    this.bankDataEpoch = (this.bankDataEpoch || 0) + 1;
    this.bankClearTimeout(this.bankRevalidateTimer);
    this.bankRevalidateTimer = null;
    if (this.bankRolloverTimer !== null && this.bankRolloverTimer !== undefined) {
      const timers = this.bankTimerApi();
      if (timers && typeof timers.clearInterval === "function") {
        timers.clearInterval(this.bankRolloverTimer);
      }
    }
    this.bankRolloverTimer = null;
    this.bankLocalDay = null;
    this.bankVaultGeneration = 0;
    if (this.bankMounts instanceof Set) {
      for (const mount of this.bankMounts) {
        if (mount) {
          mount.unloaded = true;
        }
      }
      this.bankMounts.clear();
    }
    if (this.bankCache instanceof Map) {
      this.bankCache.clear();
    }
    if (this.bankFlights instanceof Map) {
      this.bankFlights.clear();
    }
    if (this.bankPendingFetches instanceof Map) {
      for (const [key, pending] of this.bankPendingFetches) {
        const result = this.bankUnloadedResult(key);
        for (const waiter of pending.waiters || []) {
          try {
            waiter(result);
          } catch (error) {
            // Unload delivery is best-effort.
          }
        }
      }
      this.bankPendingFetches.clear();
    }
    if (this.bankLatestGeneration instanceof Map) {
      this.bankLatestGeneration.clear();
    }
    if (this.bankFetchErrors instanceof Map) this.bankFetchErrors.clear();
  }
}
// ---- src/241k-plugin-bank-actions.js ----
// Bank action service (bob-cli-kd.6.1.2): exact-selection acknowledgment,
// open-today / acknowledge-day commands, Enter continuation, category
// suggestions, and guarded ID-less checkbox edits. Pure argv/decoders and
// snapshot helpers are unit-tested; the mixin owns the desktop spawn
// boundary and cursor placement. Bob owns every total; this fragment only
// moves JSON and checkbox bytes.

// Defensive Obsidian suggest import: EditorSuggest exists on desktop but
// not in the node test stubs, so category suggestions degrade to a pure
// helper there.
let BankEditorSuggest = null;
try {
  const bankObsidianMod = require("obsidian");
  BankEditorSuggest =
    (bankObsidianMod && bankObsidianMod.EditorSuggest) || null;
} catch (error) {
  BankEditorSuggest = null;
}

const BANK_ENSURE_COMMAND_LABEL = "bob bank ensure";
const BANK_ACK_COMMAND_LABEL = "bob bank ack";
// Plain checkbox bytes for a fresh or acknowledged bank row.
const BANK_NEW_ROW_TEXT = "- [x] $";
const BANK_ROW_TASK_GESTURE_NOTICE =
  "Bank row · not a task status";
// Guards stay quiet inside tight loops; commands surface these.
const BANK_ACK_EMPTY_NOTICE = "Bank: nothing waiting on this day";
const BANK_ACK_BUSY_NOTICE = "Bank: acknowledgment already running";
const BANK_ACK_NO_DAY_NOTICE = "Bank: put the cursor on a bank day first";
const BANK_ACK_NO_IDS_NOTICE =
  "Bank: no imported rows here — tick each row's own checkbox";
const BANK_ENSURE_NO_PATH_NOTICE = "Bank: ensure returned no note path";

function bankActionText(value) {
  return typeof value === "string" ? value : "";
}

function bankEnsureArgsForDay(day) {
  const raw = bankActionText(day).trim();
  const args = ["bank", "ensure"];
  if (raw) {
    args.push("-D", raw);
  }
  args.push("-f", "json");
  return args;
}

function bankAckArgsForIds(ids) {
  const deduped = bankDedupeIds(ids);
  return ["bank", "ack", ...deduped, "-f", "json"];
}

function bankNormalizeAckId(raw) {
  const trimmed = bankActionText(raw).trim();
  if (!trimmed) {
    return "";
  }
  const noCaret = trimmed.startsWith("^") ? trimmed.slice(1) : trimmed;
  const noPrefix = noCaret.toLowerCase().startsWith("bank-")
    ? noCaret.slice(5)
    : noCaret;
  return noPrefix.trim().toLowerCase();
}

function bankDedupeIds(ids) {
  const seen = new Set();
  const out = [];
  for (const raw of Array.isArray(ids) ? ids : []) {
    const text = bankActionText(raw).trim();
    if (!text) {
      continue;
    }
    const key = bankNormalizeAckId(text);
    if (!key || seen.has(key)) {
      continue;
    }
    seen.add(key);
    out.push(text);
  }
  return out;
}

function bankDecodeEnsureResponse(stdout, stderr) {
  let body = null;
  try {
    body = JSON.parse(String(stdout === undefined ? "" : stdout));
  } catch (error) {
    return {
      ok: false,
      code: "bad-json",
      message: `${BANK_ENSURE_COMMAND_LABEL} returned output that is not JSON.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return {
      ok: false,
      code: "bad-shape",
      message: `${BANK_ENSURE_COMMAND_LABEL} returned an unexpected JSON shape.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body.schema_version !== BANK_SCHEMA_VERSION) {
    return {
      ok: false,
      code: "schema-mismatch",
      message: `${BANK_ENSURE_COMMAND_LABEL} returned schema ${String(
        body.schema_version,
      )}, this block reads schema ${BANK_SCHEMA_VERSION}.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body.ok === false) {
    const inner =
      body.error !== null && typeof body.error === "object" && !Array.isArray(body.error)
        ? body.error
        : {};
    return {
      ok: false,
      code: typeof inner.code === "string" && inner.code ? inner.code : "bob-error",
      message:
        (typeof inner.message === "string" && inner.message) ||
        (typeof body.error === "string" && body.error) ||
        `${BANK_ENSURE_COMMAND_LABEL} reported an error.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body.ok !== true) {
    return {
      ok: false,
      code: "bad-shape",
      message: `${BANK_ENSURE_COMMAND_LABEL} returned a report without ok: true.`,
      detail: statsFirstLine(stderr),
    };
  }
  const path = bankString(body.path);
  const line = bankCount(body.line);
  if (!path || line === null) {
    return {
      ok: false,
      code: "bad-shape",
      message: `${BANK_ENSURE_COMMAND_LABEL} returned no note path or row line.`,
      detail: statsFirstLine(stderr),
    };
  }
  return {
    ok: true,
    report: {
      schema_version: BANK_SCHEMA_VERSION,
      today: bankString(body.today),
      path,
      line,
      day: bankString(body.day),
      created_note: body.created_note === true,
      created_heading: body.created_heading === true,
      categories: Array.isArray(body.categories)
        ? body.categories.map(bankNormalizeCategory).filter(Boolean)
        : [],
      accounts: Array.isArray(body.accounts)
        ? body.accounts.map(bankNormalizeAccount).filter(Boolean)
        : [],
    },
  };
}

function bankDecodeAckResponse(stdout, stderr) {
  let body = null;
  try {
    body = JSON.parse(String(stdout === undefined ? "" : stdout));
  } catch (error) {
    return {
      ok: false,
      code: "bad-json",
      message: `${BANK_ACK_COMMAND_LABEL} returned output that is not JSON.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return {
      ok: false,
      code: "bad-shape",
      message: `${BANK_ACK_COMMAND_LABEL} returned an unexpected JSON shape.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (body.schema_version !== BANK_SCHEMA_VERSION) {
    return {
      ok: false,
      code: "schema-mismatch",
      message: `${BANK_ACK_COMMAND_LABEL} returned schema ${String(
        body.schema_version,
      )}, this block reads schema ${BANK_SCHEMA_VERSION}.`,
      detail: statsFirstLine(stderr),
    };
  }
  // A reported failure never needs an acknowledged list to be
  // understood: surface the CLI error first, then validate the shape.
  if (body.ok === false) {
    const inner =
      body.error !== null && typeof body.error === "object" && !Array.isArray(body.error)
        ? body.error
        : {};
    const unknown = Array.isArray(body.unknown) ? body.unknown : [];
    return {
      ok: false,
      code: typeof inner.code === "string" && inner.code ? inner.code : "bob-error",
      message:
        (typeof inner.message === "string" && inner.message) ||
        (unknown.length > 0
          ? `${BANK_ACK_COMMAND_LABEL} did not recognize: ${unknown.join(", ")}.`
          : `${BANK_ACK_COMMAND_LABEL} reported an error.`),
      detail: statsFirstLine(stderr),
      report: {
        acknowledged: Array.isArray(body.acknowledged) ? body.acknowledged : [],
        already: Array.isArray(body.already) ? body.already : [],
        unknown,
      },
    };
  }
  const acknowledged = Array.isArray(body.acknowledged) ? body.acknowledged : null;
  const already = Array.isArray(body.already) ? body.already : [];
  const unknown = Array.isArray(body.unknown) ? body.unknown : [];
  if (!acknowledged) {
    return {
      ok: false,
      code: "bad-shape",
      message: `${BANK_ACK_COMMAND_LABEL} returned no acknowledged list.`,
      detail: statsFirstLine(stderr),
    };
  }
  if (unknown.length > 0) {
    return {
      ok: false,
      code: "unknown-ids",
      message: `${BANK_ACK_COMMAND_LABEL} did not recognize: ${unknown.join(", ")}.`,
      detail: statsFirstLine(stderr),
      report: { acknowledged, already, unknown },
    };
  }
  return {
    ok: true,
    report: {
      schema_version: BANK_SCHEMA_VERSION,
      today: bankString(body.today),
      acknowledged,
      already,
      unknown,
    },
  };
}

// Waiting imported rows for one day, in displayed row order. ID-less rows
// are counted, never submitted: they need their own checkbox edit.
function bankDayWaitingSnapshot(rows, dateIso) {
  const ids = [];
  let idLess = 0;
  for (const row of Array.isArray(rows) ? rows : []) {
    if (!row || row.date !== dateIso || row.acknowledged) {
      continue;
    }
    // Source rows carry ackId (`^bank-<hex>`); JSON rows carry id.
    const ackId = typeof row.ackId === "string" && row.ackId.trim()
      ? row.ackId.trim()
      : typeof row.id === "string" && row.id.trim()
        ? row.id.trim()
        : "";
    if (ackId) {
      ids.push(ackId);
    } else {
      idLess += 1;
    }
  }
  return { ids: bankDedupeIds(ids), idLess };
}

function bankAckResultSummary(report, idLess = 0) {
  const acknowledged = report && Array.isArray(report.acknowledged)
    ? report.acknowledged.length
    : 0;
  const already = report && Array.isArray(report.already) ? report.already.length : 0;
  const remaining = Number.isInteger(idLess) && idLess > 0 ? idLess : 0;
  const parts = [];
  if (acknowledged > 0) {
    parts.push(`acknowledged ${acknowledged}`);
  }
  if (already > 0) {
    parts.push(`${already} already done`);
  }
  let text = parts.length > 0 ? `Bank: ${parts.join(", ")}` : "Bank: nothing new";
  if (remaining > 0) {
    text += ` · ${remaining} row${remaining === 1 ? "" : "s"} still need${
      remaining === 1 ? "s" : ""
    } their own checkbox`;
  }
  return {
    text,
    acknowledged,
    already,
    idLess: remaining,
    // Never report a day fully acknowledged while ID-less rows remain.
    fullyAcknowledged: acknowledged > 0 && remaining === 0,
  };
}

// Day section containing a 0-based cursor line, or null. Boundaries come
// from the shared source scan so cards and commands agree.
function bankCursorDayContext(scan, cursorLine) {
  if (!scan || !Array.isArray(scan.days)) {
    return null;
  }
  const line = Number(cursorLine);
  if (!Number.isInteger(line) || line < 0) {
    return null;
  }
  let current = null;
  for (const day of scan.days) {
    if (!day || !Number.isInteger(day.line)) {
      continue;
    }
    const headingLine = day.line - 1;
    if (headingLine <= line) {
      current = day;
    } else {
      break;
    }
  }
  return current;
}

// Guarded ID-less checkbox plan: the live buffer must still show exactly
// the rendered row, open, in a bank month note with day context. Anything
// else refuses without touching bytes.
function bankGuardedCheckboxPlan(path, source, cursorLine, expectedLineText) {
  if (bankMonthFromPath(path) === null) {
    return { ok: false, reason: "not-bank-note" };
  }
  if (typeof source !== "string") {
    return { ok: false, reason: "not-a-string" };
  }
  const lines = source.replace(/^\uFEFF/, "").split("\n");
  if (!Number.isInteger(cursorLine) || cursorLine < 0 || cursorLine >= lines.length) {
    return { ok: false, reason: "out-of-range" };
  }
  const current = lines[cursorLine].replace(/\r$/, "");
  if (bankActionText(expectedLineText) !== "" && current !== bankActionText(expectedLineText)) {
    return { ok: false, reason: "moved-or-edited" };
  }
  const lineNumber = Number(cursorLine) + 1;
  const scan = bankScanSource(path, source);
  const row = bankRecognizeRow(path, source, lineNumber);
  if (!row) {
    return { ok: false, reason: "not-a-row" };
  }
  if (row.acknowledged) {
    return { ok: false, reason: "already-acknowledged" };
  }
  // Source rows carry ackId (`^bank-<hex>`); JSON rows carry id. Either
  // way this row is imported, so only the bulk ack path may touch it.
  const rowAckId = typeof row.ackId === "string" && row.ackId.trim()
    ? row.ackId.trim()
    : typeof row.id === "string"
      ? row.id.trim()
      : "";
  if (rowAckId) {
    return { ok: false, reason: "has-id" };
  }
  const day = bankCursorDayContext(scan, cursorLine);
  if (!day || day.date !== row.date) {
    return { ok: false, reason: "no-day-context" };
  }
  // The status byte sits one char inside the `[ ]` span: replace exactly
  // one byte so the rest of the row (and undo history) is untouched.
  const statusAt = row.spans.checkbox.start + 1;
  return {
    ok: true,
    line: cursorLine,
    statusStart: statusAt,
    statusEnd: statusAt + 1,
    date: row.date,
  };
}

// Pure Enter behavior for bank month notes. Only a complete row's end
// continues, and only an exactly-empty stub clears; everything else falls
// through to ordinary Enter.
function bankEnterDecision(path, source, cursorLine, cursorCh, hasSelection) {
  if (bankMonthFromPath(path) === null) {
    return { action: "none", reason: "not-bank-note" };
  }
  if (hasSelection === true) {
    return { action: "none", reason: "selection" };
  }
  if (typeof source !== "string") {
    return { action: "none", reason: "not-a-string" };
  }
  const lines = source.replace(/^\uFEFF/, "").split("\n");
  if (!Number.isInteger(cursorLine) || cursorLine < 0 || cursorLine >= lines.length) {
    return { action: "none", reason: "out-of-range" };
  }
  const raw = lines[cursorLine].replace(/\r$/, "");
  if (!Number.isInteger(cursorCh) || cursorCh < raw.length) {
    return { action: "none", reason: "mid-line" };
  }
  const fenced = bankSourceFenceLines(source);
  if (fenced.has(cursorLine)) {
    return { action: "none", reason: "fenced" };
  }
  const classified = bankClassifyLine(raw);
  if (classified.kind === "stub") {
    const trimmed = raw.trim();
    if (trimmed === "- [x] $" || trimmed === "- [ ] $") {
      return { action: "clear-stub", line: cursorLine };
    }
    return { action: "none", reason: "not-an-empty-stub" };
  }
  if (classified.kind !== "checkbox") {
    return { action: "none", reason: "not-a-row" };
  }
  if (classified.status !== "x" && classified.status !== "X") {
    return { action: "none", reason: "not-complete" };
  }
  if (classified.lead.kind !== "amount") {
    return { action: "none", reason: "unparsed-amount" };
  }
  const row = bankRecognizeRow(path, source, Number(cursorLine) + 1);
  if (!row) {
    return { action: "none", reason: "outside-day" };
  }
  return { action: "insert-ack-row", line: cursorLine };
}

// Category suggestions in declared JSON order. Matching is a
// case-insensitive substring over key, label, and emoji; an empty query
// lists every category.
function bankCategoryCompletions(categories, query) {
  const list = Array.isArray(categories) ? categories : [];
  const needle = bankActionText(query).trim().toLowerCase();
  const out = [];
  for (const entry of list) {
    if (!entry || typeof entry.key !== "string" || !entry.key) {
      continue;
    }
    if (entry.hidden === true) {
      continue;
    }
    const haystack = `${entry.key} ${bankActionText(entry.label)} ${bankActionText(entry.emoji)}`.toLowerCase();
    if (needle && haystack.indexOf(needle) === -1) {
      continue;
    }
    out.push({ key: entry.key, label: bankActionText(entry.label), emoji: bankActionText(entry.emoji) });
  }
  return out;
}

class BobLedgerToolsBankActionsMixin {
  // One spawn boundary for both bank write commands, mirroring
  // bankSpawnFetch conventions (vault env, timeout, bounded output).
  // Tests inject execFile/resolved through spawnOptions.
  bankSpawnBankCommand(args, decoder, label, spawnOptions = {}) {
    const injected = spawnOptions && typeof spawnOptions === "object" ? spawnOptions : {};
    return bobSpawnJson(args, decoder, {
      execFile: injected.execFile,
      resolved: injected.resolved,
      tried: injected.tried,
      commandLabel: label,
      resolveBobPath: () =>
        typeof this.apiStatsBobPath === "function"
          ? this.apiStatsBobPath()
          : { path: "bob", source: "path" },
      getVaultPath: () =>
        typeof this.statsVaultBasePath === "function"
          ? this.statsVaultBasePath()
          : null,
      timeout: BOB_SPAWN_TIMEOUT_MS,
      maxBuffer: BOB_SPAWN_MAX_BUFFER,
      firstLine: statsFirstLine,
    });
  }

  setupBankActions() {
    this.bankAckPending = false;
    this.bankCategorySuggest = null;
    this.addCommand({
      id: "bank-open-today",
      name: "Bank: open today",
      callback: () => {
        void this.bankEnsureOpenDay("today").catch((error) => {
          new Notice(`Bank: could not open today (${error && error.message ? error.message : error})`);
        });
      },
    });
    this.addCommand({
      id: "bank-ack-day",
      name: "Bank: acknowledge this day",
      editorCallback: (editor, view) => {
        void this.bankAckDayAtCursor(editor, view).catch((error) => {
          new Notice(`Bank: acknowledgment failed (${error && error.message ? error.message : error})`);
        });
      },
    });
    this.addCommand({
      id: "bank-set-category",
      name: "Bank: set category",
      editorCallback: (editor, view) => {
        if (!this.bankCategorySetCategory(editor, view)) {
          new Notice("Bank: put the cursor on a bank row first");
        }
      },
    });
    if (typeof this.registerEditorExtension === "function" && keymap && typeof keymap.of === "function") {
      this.registerEditorExtension(
        keymap.of([
          {
            key: "Enter",
            run: () => this.bankHandleEnter(),
          },
        ]),
      );
    }
    this.setupBankCategorySuggest();
    this.setupBankCategoryUi();
  }

  teardownBankActions() {
    this.bankAckPending = false;
    try {
      if (this.bankCategorySuggest && typeof this.bankCategorySuggest.close === "function") {
        this.bankCategorySuggest.close();
      }
    } catch (error) {
      // Suggest teardown is best-effort.
    }
    this.bankCategorySuggest = null;
    this.teardownBankCategoryUi();
  }

  apiBankActions() {
    return Object.freeze({
      version: 2,
      ensureOpenDay: (day, options) => this.bankEnsureOpenDay(day, options),
      ackDayAtCursor: (editor, view) => this.bankAckDayAtCursor(editor, view),
      ackIds: (ids, options) => this.bankAckIds(ids, options),
      toggleIdLessRowAtCursor: (editor, expectedLineText) =>
        this.bankToggleIdLessRowAtCursor(editor, expectedLineText),
      claimRowClose: (editor, view) => this.bankCategoryClaimRowClose(editor, view),
      setCategory: (editor, view) => this.bankCategorySetCategory(editor, view),
    });
  }

  bankActiveFilePath(view = null) {
    const file = (view && view.file) ||
      (this.app && this.app.workspace && typeof this.app.workspace.getActiveFile === "function"
        ? this.app.workspace.getActiveFile()
        : null);
    return file && typeof file.path === "string" ? file.path : "";
  }

  bankActiveEditor(view = null) {
    if (view && view.editor) {
      return view.editor;
    }
    try {
      const active = this.app && this.app.workspace &&
        typeof this.app.workspace.getActiveViewOfType === "function"
        ? this.app.workspace.getActiveViewOfType(MarkdownView)
        : null;
      if (active && active instanceof MarkdownView && active.editor) {
        return active.editor;
      }
    } catch (error) {
      // Editor lookup is best-effort.
    }
    return null;
  }

  // Open-today (and daily-chip) action: ensure the day, open its note, and
  // land the cursor on the returned next-row line. JSON lines are 1-based;
  // editor lines are 0-based. Never passes `-o`: one leaf, one open.
  async bankEnsureOpenDay(day, options = {}) {
    const opts = options && typeof options === "object" ? options : {};
    const args = bankEnsureArgsForDay(day);
    const decoded = await this.bankSpawnBankCommand(
      args,
      bankDecodeEnsureResponse,
      BANK_ENSURE_COMMAND_LABEL,
      opts.spawnOptions,
    );
    if (!decoded || decoded.ok !== true || !decoded.report) {
      const message = (decoded && decoded.message) || `${BANK_ENSURE_COMMAND_LABEL} reported an error.`;
      new Notice(`Bank: ${message}`);
      return { ok: false, reason: (decoded && decoded.code) || "bob-error" };
    }
    const report = decoded.report;
    if (!report.path) {
      new Notice(`Bank: ${BANK_ENSURE_NO_PATH_NOTICE}`);
      return { ok: false, reason: "no-path" };
    }
    if (typeof this.apiBankInvalidate === "function") {
      try {
        this.apiBankInvalidate("ensure");
      } catch (error) {
        // Refresh is best-effort after a successful ensure.
      }
    }
    const opened = await this.bankOpenMonthPathAtLine(report.path, report.line);
    if (!opened) {
      new Notice("Bank: could not open the bank note");
      return { ok: false, reason: "open-failed", report };
    }
    return { ok: true, report };
  }

  async bankOpenMonthPathAtLine(path, oneBasedLine, column = 0, options = {}) {
    const opts = bankJsonObject(options) ? options : {};
    const target = bankActionText(path);
    if (!target) {
      return false;
    }
    const vault = this.app && this.app.vault;
    const file = vault && typeof vault.getAbstractFileByPath === "function"
      ? vault.getAbstractFileByPath(target)
      : null;
    if (!file) {
      return false;
    }
    // Pending saves first: bob already wrote the file on disk, so flush
    // the in-memory buffer to avoid an external-change conflict.
    if (opts.skipPendingSave !== true) {
      try {
        const leaves = this.app.workspace && typeof this.app.workspace.getLeavesOfType === "function"
          ? this.app.workspace.getLeavesOfType("markdown")
          : [];
        for (const leaf of Array.isArray(leaves) ? leaves : []) {
          const leafView = leaf && leaf.view;
          if (leafView && leafView.file && leafView.file.path === target && typeof leafView.save === "function") {
            await leafView.save();
          }
        }
      } catch (error) {
        // Save is best-effort; the open below still reloads.
      }
    }
    let openedView = null;
    if (opts.newLeaf === true) {
      try {
        const workspace = this.app && this.app.workspace;
        const leaf = workspace && typeof workspace.getLeaf === "function" ? workspace.getLeaf("tab") : null;
        if (leaf && typeof leaf.openFile === "function") {
          await leaf.openFile(file);
          openedView = leaf.view || null;
        }
      }
      catch (error) { openedView = null; }
    } else {
      try {
        const plugins = this.app && this.app.plugins && this.app.plugins.plugins;
        const nav = plugins ? plugins["bob-navigation-hotkeys"] : null;
        const openInActiveLeaf = nav && nav.api && nav.api.openFileInActiveLeaf;
        if (typeof openInActiveLeaf === "function") {
          const result = await openInActiveLeaf.call(nav.api, file);
          if (result && result.ok === true) {
            openedView = result.view || null;
          }
        }
      } catch (error) {
        openedView = null;
      }
      if (!openedView) {
        try {
          const workspace = this.app && this.app.workspace;
          const leaf = workspace && typeof workspace.getLeaf === "function" ? workspace.getLeaf(false) : null;
          if (leaf && typeof leaf.openFile === "function") {
            await leaf.openFile(file);
            openedView = leaf.view || null;
          }
        } catch (error) {
          openedView = null;
        }
      }
    }
    const editor = (openedView && openedView.editor) || this.bankActiveEditor(openedView);
    if (!editor || typeof editor.getValue !== "function") {
      return Boolean(openedView);
    }
    const zeroBased = Math.max(0, Number(oneBasedLine || 1) - 1);
    try {
      if (typeof editor.setCursor === "function") {
        editor.setCursor({ line: zeroBased, ch: Number.isInteger(column) && column > 0 ? column : 0 });
      }
      if (typeof editor.focus === "function") {
        editor.focus();
      }
    } catch (error) {
      // Cursor placement is best-effort after a successful open.
    }
    return true;
  }

  // Acknowledge-this-day: snapshot the waiting IDs under the cursor and
  // submit exactly that set. Never recomputes at click time, never sends
  // an empty selection, never falls back to `ack -D`.
  async bankAckDayAtCursor(editor, view = null, options = {}) {
    const opts = options && typeof options === "object" ? options : {};
    const path = this.bankActiveFilePath(view);
    if (!editor || typeof editor.getValue !== "function" || typeof editor.getCursor !== "function") {
      return { ok: false, reason: "no-editor" };
    }
    if (bankMonthFromPath(path) === null) {
      return { ok: false, reason: "not-bank-note" };
    }
    const source = String(editor.getValue());
    const cursor = editor.getCursor();
    const scan = bankScanSource(path, source);
    const day = bankCursorDayContext(scan, cursor && cursor.line);
    if (!day) {
      new Notice(`Bank: ${BANK_ACK_NO_DAY_NOTICE}`);
      return { ok: false, reason: "no-day" };
    }
    const snapshot = bankDayWaitingSnapshot(scan.rows, day.date);
    if (snapshot.ids.length === 0) {
      new Notice(`Bank: ${snapshot.idLess > 0 ? BANK_ACK_NO_IDS_NOTICE : BANK_ACK_EMPTY_NOTICE}`);
      return { ok: false, reason: snapshot.idLess > 0 ? "id-less-only" : "empty", day: day.date, idLess: snapshot.idLess };
    }
    return this.bankAckIds(snapshot.ids, { ...opts, label: day.date, idLess: snapshot.idLess });
  }

  // Bulk acknowledgment over an exact rendered snapshot (month/queue
  // cards pass their own IDs). Reports remaining ID-less rows and never
  // claims the day acknowledged while any remain.
  async bankAckIds(ids, options = {}) {
    const opts = options && typeof options === "object" ? options : {};
    const idLess = Number.isInteger(opts.idLess) && opts.idLess > 0 ? opts.idLess : 0;
    const label = bankActionText(opts.label) || "this day";
    if (this.bankAckPending === true) {
      new Notice(`Bank: ${BANK_ACK_BUSY_NOTICE}`);
      return { ok: false, reason: "busy" };
    }
    const deduped = bankDedupeIds(ids);
    if (deduped.length === 0) {
      new Notice(`Bank: ${BANK_ACK_EMPTY_NOTICE}`);
      return { ok: false, reason: "empty" };
    }
    this.bankAckPending = true;
    try {
      const args = bankAckArgsForIds(deduped);
      const decoded = await this.bankSpawnBankCommand(
        args,
        bankDecodeAckResponse,
        BANK_ACK_COMMAND_LABEL,
        opts.spawnOptions,
      );
      if (!decoded || decoded.ok !== true || !decoded.report) {
        const message = (decoded && decoded.message) || `${BANK_ACK_COMMAND_LABEL} reported an error.`;
        new Notice(`Bank: ${message}`);
        return { ok: false, reason: (decoded && decoded.code) || "bob-error", label };
      }
      if (typeof this.apiBankInvalidate === "function") {
        try {
          this.apiBankInvalidate("ack");
        } catch (error) {
          // Refresh is best-effort after a successful ack.
        }
      }
      const summary = bankAckResultSummary(decoded.report, idLess);
      new Notice(summary.text);
      return { ok: true, ...summary, label };
    } finally {
      this.bankAckPending = false;
    }
  }

  // Individual ID-less queue checkbox: flip exactly one status byte after
  // verifying the live row still matches the rendered snapshot and its
  // day context. Refuses ambiguous, moved, or changed rows.
  bankToggleIdLessRowAtCursor(editor, expectedLineText = "") {
    if (!editor || typeof editor.getValue !== "function" || typeof editor.getCursor !== "function") {
      return { ok: false, reason: "no-editor" };
    }
    const path = this.bankActiveFilePath(null);
    const source = String(editor.getValue());
    const cursor = editor.getCursor();
    const plan = bankGuardedCheckboxPlan(path, source, cursor && cursor.line, expectedLineText);
    if (!plan.ok) {
      return plan;
    }
    try {
      editor.replaceRange(
        "x",
        { line: plan.line, ch: plan.statusStart },
        { line: plan.line, ch: plan.statusEnd },
      );
    } catch (error) {
      return { ok: false, reason: "write-failed" };
    }
    if (typeof this.apiBankInvalidate === "function") {
      try {
        this.apiBankInvalidate("ack-checkbox");
      } catch (error) {
        // Refresh is best-effort after a successful edit.
      }
    }
    return { ok: true, line: plan.line, date: plan.date };
  }

  bankExpansionGuardTripped(editor, path) {
    try {
      if (bankMonthFromPath(path || "") === null) {
        return false;
      }
      if (!editor || typeof editor.getCursor !== "function" || typeof editor.getLine !== "function") {
        return false;
      }
      const cursor = editor.getCursor();
      if (!cursor || !Number.isInteger(cursor.line)) {
        return false;
      }
      const kind = bankClassifyLine(editor.getLine(cursor.line) || "").kind;
      return kind === "checkbox" || kind === "stub" || kind === "amount-no-checkbox";
    } catch (error) {
      return false;
    }
  }

  bankHandleEnter() {
    try {
      const view = this.app && this.app.workspace && typeof this.app.workspace.getActiveViewOfType === "function"
        ? this.app.workspace.getActiveViewOfType(MarkdownView)
        : null;
      if (!view || !(view instanceof MarkdownView) || !view.editor || !view.file) {
        return false;
      }
      const editor = view.editor;
      const path = view.file.path || "";
      if (bankMonthFromPath(path) === null) {
        return false;
      }
      if (typeof editor.listSelections === "function") {
        const selections = editor.listSelections();
        if (!Array.isArray(selections) || selections.length !== 1) {
          return false;
        }
        const selection = selections[0];
        if (!sameEditorPosition(selection.anchor, selection.head)) {
          return false;
        }
      }
      if (typeof editor.getCursor !== "function" || typeof editor.getValue !== "function") {
        return false;
      }
      const cursor = editor.getCursor();
      const source = String(editor.getValue());
      const decision = bankEnterDecision(path, source, cursor.line, cursor.ch, false);
      if (decision.action === "insert-ack-row") {
        const anchor = { line: decision.line, ch: String(source.split("\n")[decision.line] || "").replace(/\r$/, "").length };
        editor.replaceRange(`\n${BANK_NEW_ROW_TEXT}`, anchor, anchor);
        if (typeof editor.setCursor === "function") {
          editor.setCursor({ line: decision.line + 1, ch: BANK_NEW_ROW_TEXT.length });
        }
        return true;
      }
      if (decision.action === "clear-stub") {
        const raw = String(source.split("\n")[decision.line] || "").replace(/\r$/, "");
        editor.replaceRange("", { line: decision.line, ch: 0 }, { line: decision.line, ch: raw.length });
        return true;
      }
      return false;
    } catch (error) {
      return false;
    }
  }

  bankLastCategories() {
    try {
      const store = typeof this.bankCacheStore === "function" ? this.bankCacheStore() : null;
      if (!store || typeof store.values !== "function") {
        return [];
      }
      for (const entry of store.values()) {
        const report = entry && entry.report;
        if (report && Array.isArray(report.categories) && report.categories.length > 0) {
          return report.categories;
        }
      }
    } catch (error) {
      // Category lookup is best-effort.
    }
    return [];
  }

  // `[cat:: ` suggestions from JSON categories in declared order. Only
  // the key is inserted. No default hotkey; the suggest owns its popup.
  setupBankCategorySuggest() {
    try {
      if (!BankEditorSuggest || typeof this.registerEditorSuggest !== "function") {
        return;
      }
      const plugin = this;
      class BankCategorySuggest extends BankEditorSuggest {
        constructor(app) {
          super(app, plugin);
          this.pluginRef = plugin;
        }

        onTrigger(cursor, editor, file) {
          try {
            const path = (file && file.path) || "";
            if (bankMonthFromPath(path) === null) {
              return null;
            }
            const line = editor.getLine(cursor.line) || "";
            const before = line.slice(0, cursor.ch);
            const match = before.match(/\[cat::\s*([^\]\n]*)$/);
            if (!match) {
              return null;
            }
            const classified = bankClassifyLine(line);
            if (classified.kind !== "checkbox" && classified.kind !== "stub" && classified.kind !== "amount-no-checkbox") {
              return null;
            }
            return { start: { line: cursor.line, ch: cursor.ch - match[1].length }, end: cursor, query: match[1] };
          } catch (error) {
            return null;
          }
        }

        getSuggestions(context) {
          try {
            return bankCategoryCompletions(this.pluginRef.bankLastCategories(), context && context.query);
          } catch (error) {
            return [];
          }
        }

        renderSuggestion(value, el) {
          try {
            el.setText(`${bankActionText(value.emoji) ? `${value.emoji} ` : ""}${value.label || value.key}`);
          } catch (error) {
            // Rendering is best-effort.
          }
        }

        selectSuggestion(value) {
          try {
            const editor = (this.context && this.context.editor) || null;
            const start = this.context && this.context.start;
            const end = this.context && this.context.end;
            if (editor && start && end && value && value.key) {
              editor.replaceRange(value.key, start, end);
            }
          } catch (error) {
            // Selection is best-effort.
          } finally {
            try {
              this.close();
            } catch (error) {
              // Close is best-effort.
            }
          }
        }
      }
      this.bankCategorySuggest = new BankCategorySuggest(this.app);
      this.registerEditorSuggest(this.bankCategorySuggest);
    } catch (error) {
      this.bankCategorySuggest = null;
    }
  }
}
// ---- src/241l-plugin-bank-cards-model.js ----
// Pure presentation models for the month and queue bank cards, plus the
// daily-note bank chip. Bob supplies every amount and count.

const BANK_CARD_HUES = ["aqua", "blue", "green", "magenta", "orange", "red", "violet", "yellow"];
const BANK_CARD_HEAT_LEVELS = 4;

function bankCardParseFence(source) {
  const values = new Map();
  const errors = [];
  const lines = typeof source === "string" ? source.split(/\r?\n/) : [];
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index].replace(/\s+#.*$/, "").trim();
    if (!raw || raw.startsWith("#")) continue;
    const match = /^([A-Za-z][A-Za-z0-9_-]*)\s*:\s*(.*?)\s*$/.exec(raw);
    if (!match) {
      errors.push(`Line ${index + 1}: use "view: month" or "view: queue".`);
      continue;
    }
    const key = match[1].toLowerCase();
    if (key !== "view") {
      errors.push(`Unknown option "${match[1]}". This fence accepts only "view".`);
      continue;
    }
    if (values.has(key)) {
      errors.push("Use one view option.");
      continue;
    }
    values.set(key, match[2].replace(/^(?:"([^"]*)"|'([^']*)')$/, (_, a, b) => a || b));
  }
  const view = values.get("view");
  if (!view) errors.push("Add " + '"view: month"' + " or " + '"view: queue"' + ".");
  else if (view !== "month" && view !== "queue") errors.push(`Unknown view "${view}". Use month or queue.`);
  return errors.length ? { ok: false, errors } : { ok: true, view };
}

function bankCardValidateMonthFrontmatter(path, value) {
  const fileMonth = bankMonthFromPath(path);
  const month = typeof value === "string" ? value.trim() : "";
  if (!fileMonth) {
    return { ok: false, code: "month-path", message: "Month cards belong in bank/YYYY-MM.md." };
  }
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
    return { ok: false, code: "month-frontmatter", message: "Add a month: YYYY-MM value to this note's frontmatter." };
  }
  if (month !== fileMonth.key) {
    return {
      ok: false,
      code: "month-mismatch",
      message: `Frontmatter month ${month} does not match this file's ${fileMonth.key} name.`,
    };
  }
  return { ok: true, month };
}

function bankCardDate(day) {
  return typeof day === "string" && /^\d{4}-\d{2}-\d{2}$/.test(day)
    ? day
    : null;
}

function bankCardDaysInMonth(month) {
  if (typeof month !== "string" || !/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) return 0;
  const [year, monthNumber] = month.split("-").map(Number);
  return new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
}

function bankCardIsoDate(month, dayNumber) {
  if (bankCardDaysInMonth(month) < dayNumber || dayNumber < 1) return null;
  return `${month}-${String(dayNumber).padStart(2, "0")}`;
}

function bankCardHeatBuckets(days) {
  const sorted = (Array.isArray(days) ? days : [])
    .map((day) => day && day.out_cents)
    .filter((cents) => Number.isSafeInteger(cents) && cents > 0)
    .sort((left, right) => left - right);
  const spans = new Map();
  for (let index = 0; index < sorted.length; index += 1) {
    const value = sorted[index];
    const span = spans.get(value) || { start: index, end: index };
    span.end = index;
    spans.set(value, span);
  }
  const buckets = new Map();
  for (const [value, span] of spans) {
    const midpoint = (span.start + span.end) / 2;
    const bucket = Math.min(
      BANK_CARD_HEAT_LEVELS,
      Math.floor((midpoint / Math.max(sorted.length, 1)) * BANK_CARD_HEAT_LEVELS) + 1,
    );
    buckets.set(value, bucket);
  }
  return buckets;
}

function bankCardMonthHeatModel(month, reportDays, options = {}) {
  const count = bankCardDaysInMonth(month);
  if (!count) return null;
  const days = Array.isArray(reportDays) ? reportDays : [];
  const byDate = new Map(days.filter((day) => day && bankCardDate(day.date)).map((day) => [day.date, day]));
  const headingDates = options.headingDates instanceof Set
    ? options.headingDates
    : new Set(Array.isArray(options.headingDates) ? options.headingDates : []);
  const today = bankCardDate(options.today) || "";
  const heatBuckets = bankCardHeatBuckets(days);
  const cells = [];
  for (let number = 1; number <= count; number += 1) {
    const date = bankCardIsoDate(month, number);
    const source = byDate.get(date) || null;
    const outCents = source && Number.isSafeInteger(source.out_cents) ? Math.max(0, source.out_cents) : 0;
    const weekday = (new Date(`${date}T00:00:00Z`).getUTCDay() + 6) % 7;
    cells.push({
      date,
      day: number,
      weekday,
      outCents,
      bucket: outCents === 0 ? 0 : (heatBuckets.get(outCents) || 1),
      waiting: source && Number.isInteger(source.waiting) ? source.waiting : 0,
      today: date === today,
      hasHeading: headingDates.has(date),
      heading: source && typeof source.heading === "string" ? source.heading : "",
    });
  }
  const first = cells[0];
  return {
    month,
    leading: first ? first.weekday : 0,
    weekdays: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
    cells,
  };
}

function bankCardMonthModel(report, month, options = {}) {
  if (report && report.teaching_empty === true) {
    return { kind: "teaching-empty", command: "report" };
  }
  const period = report && report.period;
  if (
    !report ||
    report.command !== "report" ||
    !period ||
    period.kind !== "month" ||
    period.key !== month ||
    !report.totals ||
    !Array.isArray(report.breakdown) ||
    !Array.isArray(report.days)
  ) {
    return { kind: "invalid-report", message: "bob bank report did not return this month." };
  }
  const heat = bankCardMonthHeatModel(month, report.days, {
    headingDates: options.headingDates,
    today: report.today,
  });
  if (!heat) return { kind: "invalid-report", message: "This note does not name a valid bank month." };
  const waitingRows = [];
  for (const day of report.days) {
    for (const row of Array.isArray(day.rows) ? day.rows : []) {
      if (row && row.acknowledged === false) {
        waitingRows.push({ ...row, date: row.date || day.date, path: row.path || day.path });
      }
    }
  }
  waitingRows.sort((left, right) =>
    String(left.date || "").localeCompare(String(right.date || "")) ||
    Number(left.line || 0) - Number(right.line || 0),
  );
  return {
    kind: "month",
    month,
    title: period.label || month,
    soFar: period.so_far === true,
    accounts: Array.isArray(report.accounts) ? report.accounts : [],
    totals: report.totals,
    waiting: report.waiting && Number.isInteger(report.waiting.period) ? report.waiting.period : 0,
    flagged: Number.isInteger(report.flagged) ? report.flagged : 0,
    breakdown: report.breakdown.map((entry) => ({
      ...entry,
      share: Math.max(0, Math.min(1, Number.isFinite(entry.share) ? entry.share : 0)),
    })),
    days: heat.cells,
    heat,
    firstWaiting: waitingRows[0] || null,
    empty: waitingRows.length === 0 && report.days.every((day) => !day.rows || day.rows.length === 0),
    monthPaths: Array.isArray(options.monthPaths) ? options.monthPaths : [],
  };
}

function bankCardDedupeIds(ids) {
  return bankDedupeIds(ids);
}

function bankCardRecentMonths(paths, reports, limit = 6) {
  const entries = Array.isArray(paths) ? paths : [];
  const byMonth = reports instanceof Map ? reports : new Map(Object.entries(reports || {}));
  return entries
    .filter((entry) => entry && typeof entry.month === "string" && bankMonthFromPath(entry.path))
    .slice()
    .sort((left, right) => right.month.localeCompare(left.month))
    .slice(0, Math.max(0, Math.min(6, Number.isInteger(limit) ? limit : 6)))
    .map((entry) => {
      const result = byMonth.get(entry.month) || null;
      const report = result && result.report ? result.report : result;
      const valid = report && report.command === "report" && report.period && report.period.key === entry.month && report.period.kind === "month";
      return {
        path: entry.path,
        month: entry.month,
        report: valid ? report : null,
        outCents: valid && report.totals && Number.isSafeInteger(report.totals.out_cents) ? report.totals.out_cents : null,
        label: valid ? (report.period.label || entry.month) : entry.month,
        stale: Boolean(result && result.stale),
        error: result && result.error ? result.error : null,
      };
    });
}

function bankCardQueueModel(report, options = {}) {
  if (report && report.teaching_empty === true) {
    return { kind: "teaching-empty", command: "list" };
  }
  if (!report || report.command !== "list" || !Array.isArray(report.days)) {
    return { kind: "invalid-report", message: "bob bank list did not return a waiting queue." };
  }
  const rows = [];
  for (const day of report.days) {
    for (const row of Array.isArray(day.rows) ? day.rows : []) {
      if (!row || row.acknowledged === true) continue;
      rows.push({
        ...row,
        date: row.date || day.date || "",
        path: row.path || day.path || "",
        heading: day.heading || "",
        dayLine: day.line,
      });
    }
  }
  rows.sort((left, right) =>
    String(left.date).localeCompare(String(right.date)) ||
    String(left.path).localeCompare(String(right.path)) ||
    Number(left.line || 0) - Number(right.line || 0),
  );
  const byDay = new Map();
  for (const row of rows) {
    const key = `${row.path}\u0000${row.date}`;
    if (!byDay.has(key)) {
      byDay.set(key, {
        path: row.path,
        date: row.date,
        heading: row.heading,
        line: row.dayLine,
        rows: [],
        ids: [],
        idLess: 0,
      });
    }
    const group = byDay.get(key);
    group.rows.push(row);
    if (typeof row.id === "string" && row.id.trim()) group.ids.push(row.id.trim());
    else group.idLess += 1;
  }
  const days = Array.from(byDay.values()).map((day) => ({ ...day, ids: bankCardDedupeIds(day.ids) }));
  const monthPaths = Array.isArray(options.monthPaths) ? options.monthPaths : [];
  const recentMonths = bankCardRecentMonths(monthPaths, options.monthReports, 6);
  return {
    kind: "queue",
    today: report.today || "",
    accounts: Array.isArray(report.accounts) ? report.accounts : [],
    counts: report.counts || { rows: rows.length, waiting: rows.length, flagged: 0 },
    rows,
    days,
    empty: rows.length === 0,
    recentMonths,
  };
}

// ---- src/241m-plugin-bank-cards.js ----
// `bob-bank` month and queue cards. The renderer consumes only versioned
// bank JSON and delegates every write to the shared bank action service.

function bankCardAppend(parent, tag, attrs = {}, text = undefined) {
  const doc = statsDocFor(parent);
  const node = statsEl(doc, tag, attrs, text);
  if (node && parent && typeof parent.appendChild === "function") parent.appendChild(node);
  return node;
}

function bankCardClear(parent) {
  try {
    if (typeof parent.empty === "function") parent.empty();
    else if (typeof parent.replaceChildren === "function") parent.replaceChildren();
    else parent.textContent = "";
  } catch (error) {
    // A detached Markdown block may reject cleanup; it can render on retry.
  }
}

function bankCardListen(node, event, listener) {
  if (!node || typeof node.addEventListener !== "function" || typeof listener !== "function") return;
  node.addEventListener(event, listener);
}

function bankCardSetData(node, name, value) {
  try {
    if (node && typeof node.setAttribute === "function") node.setAttribute(`data-${name}`, String(value));
  } catch (error) {
    // Styling metadata is cosmetic.
  }
}

function bankCardPercent(value) {
  return `${(Math.max(0, Math.min(1, Number(value) || 0)) * 100).toFixed(1)}%`;
}

function bankCardDisplayCents(cents, explicitPlus = false) {
  const value = Number.isSafeInteger(cents) ? bankFormatCents(cents) : null;
  return value && !explicitPlus ? value.replace(/^\+/, "") : value;
}

class BobLedgerToolsBankCardsMixin {
  setupBankCards() {
    this.bankCardViews = new Set();
    if (typeof this.registerMarkdownCodeBlockProcessor === "function") {
      this.registerMarkdownCodeBlockProcessor("bob-bank", (source, el, ctx) =>
        this.renderBankCard(el, ctx, source),
      );
    }
  }

  teardownBankCards() {
    if (this.bankCardViews instanceof Set) {
      for (const view of Array.from(this.bankCardViews)) this.bankCardReleaseView(view);
      this.bankCardViews.clear();
    }
  }

  bankCardReleaseView(view) {
    if (!view || view.unloaded) return;
    view.unloaded = true;
    view.paintGeneration = (view.paintGeneration || 0) + 1;
    try { if (typeof view.unsubscribe === "function") view.unsubscribe(); } catch (error) {}
    try { if (typeof view.monthUnsubscribe === "function") view.monthUnsubscribe(); } catch (error) {}
    view.unsubscribe = null;
    view.monthUnsubscribe = null;
    if (this.bankCardViews instanceof Set) this.bankCardViews.delete(view);
  }

  renderBankCard(el, ctx, source) {
    if (!el) return;
    const fence = bankCardParseFence(source);
    if (!fence.ok) {
      bankCardClear(el);
      const error = bankCardAppend(el, "div", {
        class: "bob-bank-card-error",
        role: "alert",
        "aria-label": "Invalid bob-bank options",
      });
      if (error) {
        bankCardAppend(error, "strong", {}, "This bank card needs a valid view.");
        for (const message of fence.errors) bankCardAppend(error, "div", {}, message);
      }
      return;
    }
    const sourcePath = ctx && typeof ctx.sourcePath === "string" ? ctx.sourcePath : "";
    let month = null;
    if (fence.view === "month") {
      const frontmatter = this.bankCardFrontmatter(sourcePath);
      const validated = bankCardValidateMonthFrontmatter(sourcePath, frontmatter && frontmatter.month);
      if (!validated.ok) {
        bankCardClear(el);
        const error = bankCardAppend(el, "div", { class: "bob-bank-card-error", role: "alert" }, validated.message);
        if (error) error.setAttribute("aria-label", "Invalid bank month note");
        return;
      }
      month = validated.month;
    }
    const view = {
      el,
      sourcePath,
      kind: fence.view,
      month,
      dataKey: bankCacheKey(fence.view === "month"
        ? bankBuildArgs({ command: "report", month })
        : bankBuildArgs({ command: "list" })),
      dataState: null,
      monthState: null,
      monthPaths: [],
      monthSignature: "",
      paintGeneration: 0,
      unloaded: false,
    };
    this.bankCardViewsStore().add(view);
    const release = () => this.bankCardReleaseView(view);
    if (ctx && typeof ctx.addChild === "function") {
      let child = null;
      try {
        if (typeof MarkdownRenderChild === "function") {
          child = new MarkdownRenderChild(el);
          child.onunload = release;
        }
      } catch (error) {
        child = null;
      }
      if (!child) child = { unload: release };
      try { ctx.addChild(child); } catch (error) {}
    }
    const spec = fence.view === "month"
      ? { command: "report", month }
      : { command: "list" };
    view.unsubscribe = this.apiBankSubscribe(spec, (state) => {
      if (view.unloaded) return;
      view.dataState = state;
      if (view.kind === "queue") this.bankCardSyncQueueMonths(view);
      void this.bankCardPaint(view);
    });
    if (view.kind === "queue") this.bankCardSyncQueueMonths(view);
  }

  bankCardViewsStore() {
    if (!(this.bankCardViews instanceof Set)) this.bankCardViews = new Set();
    return this.bankCardViews;
  }

  bankCardFrontmatter(path) {
    try {
      const vault = this.app && this.app.vault;
      const file = vault && typeof vault.getAbstractFileByPath === "function"
        ? vault.getAbstractFileByPath(path)
        : null;
      const cacheApi = this.app && this.app.metadataCache;
      const cache = file && cacheApi && typeof cacheApi.getFileCache === "function"
        ? cacheApi.getFileCache(file)
        : cacheApi && typeof cacheApi.getCache === "function"
          ? cacheApi.getCache(path)
          : null;
      return cache && cache.frontmatter && typeof cache.frontmatter === "object"
        ? cache.frontmatter
        : null;
    } catch (error) {
      return null;
    }
  }

  bankCardMonthPaths() {
    try {
      return typeof this.apiBankMonthPaths === "function" ? this.apiBankMonthPaths() : [];
    } catch (error) {
      return [];
    }
  }

  bankCardSyncQueueMonths(view) {
    if (!view || view.unloaded || view.kind !== "queue") return;
    const paths = this.bankCardMonthPaths()
      .slice()
      .sort((left, right) => String(right.month).localeCompare(String(left.month)))
      .slice(0, 6);
    const signature = paths.map((entry) => `${entry.month}:${entry.path}`).join("|");
    if (signature === view.monthSignature) return;
    view.monthSignature = signature;
    view.monthPaths = paths;
    try { if (typeof view.monthUnsubscribe === "function") view.monthUnsubscribe(); } catch (error) {}
    view.monthUnsubscribe = null;
    view.monthState = null;
    if (paths.length === 0) return;
    const fetches = paths.map((entry) => ({ command: "report", month: entry.month }));
    view.monthUnsubscribe = this.apiBankSubscribe({ fetches }, (state) => {
      if (view.unloaded) return;
      view.monthState = state;
      void this.bankCardPaint(view);
    });
  }

  bankCardCurrentResult(view, state = view && view.dataState, key = view && view.dataKey) {
    try { return state && state.results && state.results[key] ? state.results[key] : null; } catch (error) { return null; }
  }

  async bankCardReadSource(path) {
    try {
      const vault = this.app && this.app.vault;
      const file = vault && typeof vault.getAbstractFileByPath === "function"
        ? vault.getAbstractFileByPath(path)
        : null;
      if (!file || !vault || typeof vault.cachedRead !== "function") return null;
      const source = await vault.cachedRead(file);
      return typeof source === "string" ? source : null;
    } catch (error) {
      return null;
    }
  }

  async bankCardPaint(view) {
    if (!view || view.unloaded) return;
    const generation = (view.paintGeneration || 0) + 1;
    view.paintGeneration = generation;
    let source = null;
    let headingDates = new Set();
    if (view.kind === "month") {
      source = await this.bankCardReadSource(view.sourcePath);
      if (source !== null) {
        const scan = bankScanSource(view.sourcePath, source);
        headingDates = new Set(scan.days.map((day) => day.date));
      }
    }
    if (view.unloaded || view.paintGeneration !== generation) return;
    bankCardClear(view.el);
    const root = bankCardAppend(view.el, "section", {
      class: `bob-bank-card bob-bank-card-${view.kind}`,
      role: "region",
      "aria-label": view.kind === "month" ? "Bank month summary" : "Bank rows waiting for acknowledgment",
    });
    if (!root) return;
    const hue = this.bankCardRootHue(view.sourcePath);
    if (hue) root.setAttribute("data-root-hue", hue);
    const keyResult = this.bankCardCurrentResult(view);
    this.bankCardPaintRefreshState(root, keyResult, view, view.kind === "month"
      ? { command: "report", month: view.month }
      : { command: "list" });
    if (!keyResult || !keyResult.report) {
      this.bankCardPaintUnavailable(root, keyResult, view.kind);
      return;
    }
    if (keyResult.report.teaching_empty === true) {
      this.bankCardPaintTeaching(root);
      return;
    }
    if (view.kind === "month") {
      const model = bankCardMonthModel(keyResult.report, view.month, {
        headingDates,
        monthPaths: this.bankCardMonthPaths(),
      });
      if (model.kind === "invalid-report") {
        bankCardAppend(root, "p", { class: "bob-bank-card-error", role: "alert" }, model.message);
        return;
      }
      this.bankCardRenderMonth(root, view, model);
    } else {
      const monthReports = new Map();
      for (const entry of view.monthPaths) {
        const key = bankCacheKey(bankBuildArgs({ command: "report", month: entry.month }));
        const result = this.bankCardCurrentResult(view, view.monthState, key);
        monthReports.set(entry.month, result);
      }
      const model = bankCardQueueModel(keyResult.report, {
        monthPaths: view.monthPaths,
        monthReports,
      });
      if (model.kind === "invalid-report") {
        bankCardAppend(root, "p", { class: "bob-bank-card-error", role: "alert" }, model.message);
        return;
      }
      this.bankCardRenderQueue(root, view, model);
    }
  }

  bankCardRootHue(path) {
    const candidatePaths = [path, "bank.md"];
    for (const candidate of candidatePaths) {
      try {
        const file = this.app && this.app.vault && this.app.vault.getAbstractFileByPath(candidate);
        const cacheApi = this.app && this.app.metadataCache;
        const cache = file && cacheApi && typeof cacheApi.getFileCache === "function"
          ? cacheApi.getFileCache(file)
          : null;
        const hue = cache && cache.frontmatter && cache.frontmatter.color;
        if (BANK_CARD_HUES.includes(hue)) return hue;
      } catch (error) {}
    }
    return "magenta";
  }

  bankCardPaintRefreshState(root, result, view, options) {
    if (result && result.stale) {
      bankCardAppend(root, "div", { class: "bob-bank-card-status", role: "status" }, "Updating · last good values shown");
    }
    if (result && result.error) {
      const model = bankErrorModel(result.error);
      const line = bankCardAppend(root, "div", { class: "bob-bank-card-error", role: "status" });
      if (line) {
        bankCardAppend(line, "span", {}, `${model.title}: ${model.hint}`);
        if (model.retry) {
          const retry = bankCardAppend(line, "button", { type: "button", class: "bob-bank-retry" }, "Retry");
          bankCardListen(retry, "click", () => {
            void this.apiBankRefresh(options).then((next) => {
              if (next && next.error && !view.unloaded) new Notice(next.error.message || "Bank refresh failed");
            });
          });
        }
      }
    }
  }

  bankCardPaintUnavailable(root, result, kind) {
    if (result && result.error) {
      const model = bankErrorModel(result.error);
      bankCardAppend(root, "h2", {}, model.title);
      bankCardAppend(root, "p", {}, model.hint);
      return;
    }
    bankCardAppend(root, "p", { class: "bob-bank-loading", role: "status" },
      kind === "month" ? "Loading this month's bank report…" : "Loading rows to acknowledge…");
  }

  bankCardPaintTeaching(root) {
    const empty = bankCardAppend(root, "div", { class: "bob-bank-teaching" });
    if (!empty) return;
    bankCardAppend(empty, "h2", {}, "Start with the bank hub");
    bankCardAppend(empty, "p", {}, "Create bank.md and configure at least one account before these views can show totals.");
    bankCardAppend(empty, "code", {}, "bob bank list -f json");
  }

  bankCardAccounts(parent, accounts, options = {}) {
    const section = bankCardAppend(parent, "div", { class: "bob-bank-accounts", "aria-label": "Account status" });
    if (!section) return;
    bankCardAppend(section, "span", { class: "bob-bank-section-label" }, "Accounts");
    for (const account of Array.isArray(accounts) ? accounts : []) {
      const card = bankCardAppend(section, "div", { class: "bob-bank-account" });
      if (!card) continue;
      const label = account.label || account.alias || "Account";
      const status = account.status || "status unavailable";
      bankCardAppend(card, "span", { class: "bob-bank-account-name" }, label);
      bankCardAppend(card, "span", { class: `bob-bank-account-state bob-bank-state-${String(status).replace(/[^a-z0-9_-]/gi, "-")}` }, status);
      if (account.hint) bankCardAppend(card, "span", { class: "bob-bank-account-hint" }, account.hint);
      if (options.lastImport && account.last_import) {
        bankCardAppend(card, "span", { class: "bob-bank-account-import" }, `Last import ${account.last_import}`);
      } else if (options.lastImport) {
        bankCardAppend(card, "span", { class: "bob-bank-account-import" }, "No import yet");
      }
    }
  }

  bankCardMoney(parent, label, cents, options = {}) {
    const metric = bankCardAppend(parent, "div", { class: `bob-bank-metric${options.tone ? ` bob-bank-metric-${options.tone}` : ""}` });
    if (!metric) return;
    bankCardAppend(metric, "span", { class: "bob-bank-metric-label" }, label);
    const value = bankCardDisplayCents(cents, options.explicitPlus === true);
    bankCardAppend(metric, "strong", { class: "bob-bank-money" }, value || "—");
  }

  bankCardButton(parent, label, text, handler, options = {}) {
    const button = bankCardAppend(parent, "button", {
      type: "button",
      class: options.class || "bob-bank-button",
      "aria-label": label,
      title: options.title,
    }, text);
    if (button) {
      if (options.disabled) button.disabled = true;
      bankCardListen(button, "click", (event) => {
        if (event && typeof event.preventDefault === "function") event.preventDefault();
        if (!options.disabled && typeof handler === "function") void handler(event);
      });
    }
    return button;
  }

  bankCardRenderMonth(root, view, model) {
    const header = bankCardAppend(root, "header", { class: "bob-bank-card-header" });
    bankCardAppend(header, "h2", {}, model.title);
    if (model.soFar) bankCardAppend(header, "span", { class: "bob-bank-so-far" }, "so far");
    this.bankCardAccounts(root, model.accounts);
    const totals = bankCardAppend(root, "div", { class: "bob-bank-summary", "aria-label": "Month totals" });
    this.bankCardMoney(totals, "Out", model.totals.out_cents);
    this.bankCardMoney(totals, "In", model.totals.in_cents, { tone: "in", explicitPlus: true });
    this.bankCardMoney(totals, "Net", model.totals.net_cents, { tone: "net", explicitPlus: true });
    const counts = bankCardAppend(root, "div", { class: "bob-bank-counts" });
    const waitingText = `${model.waiting} waiting`;
    this.bankCardButton(counts, `Jump to first waiting bank row (${model.waiting})`, waitingText, () =>
      model.firstWaiting ? this.bankCardNavigateRow(model.firstWaiting) : false,
    { class: "bob-bank-pill bob-bank-waiting", disabled: !model.firstWaiting || model.waiting === 0 });
    bankCardAppend(counts, "span", { class: "bob-bank-pill bob-bank-flagged" }, `${model.flagged} flagged`);
    const categories = bankCardAppend(root, "section", { class: "bob-bank-breakdown", "aria-label": "Out by category" });
    bankCardAppend(categories, "h3", {}, "Out by category");
    for (const entry of model.breakdown) {
      const row = bankCardAppend(categories, "div", { class: "bob-bank-category" });
      bankCardAppend(row, "span", { class: "bob-bank-category-name" }, `${entry.emoji ? `${entry.emoji} ` : ""}${entry.label}`);
      const track = bankCardAppend(row, "span", {
        class: "bob-bank-category-track",
        role: "img",
        "aria-label": `${entry.label}: ${bankCardPercent(entry.share)} of Out`,
      });
      if (track) {
        const fill = bankCardAppend(track, "span", { class: "bob-bank-category-fill" });
        if (fill && fill.style) fill.style.width = bankCardPercent(entry.share);
      }
      bankCardAppend(row, "span", { class: "bob-bank-money" }, bankCardDisplayCents(entry.out_cents) || "—");
      bankCardAppend(row, "span", { class: "bob-bank-share" }, bankCardPercent(entry.share));
    }
    const extras = bankCardAppend(root, "div", { class: "bob-bank-extra-totals" });
    bankCardAppend(extras, "span", {}, `Unclassified: ${bankCardDisplayCents(model.totals.unclassified_out_cents) || "—"} out · ${bankCardDisplayCents(model.totals.unclassified_in_cents, true) || "—"} in`);
    if (model.totals.cash_out_cents > 0) {
      bankCardAppend(extras, "span", { class: "bob-bank-cash-note" }, `Cash out ${bankCardDisplayCents(model.totals.cash_out_cents)} · destination unknown`);
    }
    if (model.empty) {
      bankCardAppend(root, "p", { class: "bob-bank-empty-month" }, "Nothing posted in this month yet. Add a day heading, then type a checked row such as - [x] $13.71 Shop.");
    }
    this.bankCardRenderHeat(root, view, model);
    this.bankCardRenderMonthFooter(root, view, model);
  }

  bankCardRenderHeat(root, view, model) {
    const section = bankCardAppend(root, "section", { class: "bob-bank-heat-section", "aria-label": "Daily Out heat strip" });
    bankCardAppend(section, "h3", {}, "Daily Out");
    const grid = bankCardAppend(section, "div", { class: "bob-bank-heat-grid", role: "group", "aria-label": "Monday-first days of the month" });
    for (const label of model.heat.weekdays) bankCardAppend(grid, "span", { class: "bob-bank-weekday", "aria-hidden": "true" }, label.slice(0, 1));
    for (let index = 0; index < model.heat.leading; index += 1) bankCardAppend(grid, "span", { class: "bob-bank-heat-pad", "aria-hidden": "true" });
    for (const day of model.days) {
      const title = `${day.date} · Out ${bankCardDisplayCents(day.outCents) || "—"}${day.waiting ? ` · ${day.waiting} waiting` : ""}`;
      const button = this.bankCardButton(grid,
        day.hasHeading ? `Open ${day.heading || day.date}` : `${day.date}; no day heading in this note`,
        String(day.day),
        () => this.bankCardNavigateDay(view.sourcePath, day.date),
        { class: `bob-bank-heat-day bob-bank-heat-${day.bucket}${day.today ? " is-today" : ""}${day.waiting ? " has-waiting" : ""}`, disabled: !day.hasHeading, title },
      );
      if (button) {
        bankCardSetData(button, "heat", day.bucket);
        bankCardSetData(button, "date", day.date);
        if (day.waiting) bankCardAppend(button, "span", { class: "bob-bank-heat-waiting", "aria-hidden": "true" }, "•");
      }
    }
  }

  bankCardRenderMonthFooter(root, view, model) {
    const footer = bankCardAppend(root, "footer", { class: "bob-bank-card-footer" });
    const paths = model.monthPaths
      .filter((entry) => entry && entry.month && entry.month !== model.month)
      .slice()
      .sort((left, right) => left.month.localeCompare(right.month));
    const previous = paths.filter((entry) => entry.month < model.month).slice(-1)[0] || null;
    const next = paths.find((entry) => entry.month > model.month) || null;
    if (previous) this.bankCardOpenNoteLink(footer, `← ${previous.month}`, previous.path, view.sourcePath);
    else bankCardAppend(footer, "span", { class: "bob-bank-footer-muted" }, "No earlier month");
    if (this.bankCardHasHub()) this.bankCardOpenNoteLink(footer, "Bank hub", "bank.md", view.sourcePath);
    else bankCardAppend(footer, "span", { class: "bob-bank-footer-muted" }, "Bank hub missing");
    if (next) this.bankCardOpenNoteLink(footer, `${next.month} →`, next.path, view.sourcePath);
    else bankCardAppend(footer, "span", { class: "bob-bank-footer-muted" }, "No later month");
  }

  bankCardRenderQueue(root, view, model) {
    this.bankCardAccounts(root, model.accounts, { lastImport: true });
    if (model.empty) {
      bankCardAppend(root, "p", { class: "bob-bank-empty-queue", role: "status" }, "Nothing to acknowledge");
    }
    for (const day of model.days) {
      const group = bankCardAppend(root, "section", { class: "bob-bank-queue-day" });
      const header = bankCardAppend(group, "header", { class: "bob-bank-queue-day-header" });
      this.bankCardButton(header, `Open bank rows for ${day.date}`, day.heading || day.date,
        () => this.bankCardNavigateDay(day.path, day.date),
        { class: "bob-bank-day-link" },
      );
      const ackButton = this.bankCardButton(header,
        `Acknowledge ${day.ids.length} displayed imported rows for ${day.date}`,
        day.ids.length ? `Acknowledge ${day.ids.length} imported` : "No imported rows to acknowledge",
        () => this.bankCardAckSnapshot(day),
        { class: "bob-bank-ack-day", disabled: day.ids.length === 0 },
      );
      if (day.idLess > 0) {
        bankCardAppend(group, "p", { class: "bob-bank-idless-note" }, `${day.idLess} typed ${day.idLess === 1 ? "row needs" : "rows need"} its individual checkbox.`);
      }
      if (ackButton) bankCardSetData(ackButton, "ack-ids", day.ids.join(" "));
      for (const row of day.rows) this.bankCardRenderQueueRow(group, view, row);
    }
    this.bankCardRenderQueueFooter(root, view, model);
  }

  bankCardRenderQueueRow(parent, view, row) {
    const line = bankCardAppend(parent, "div", { class: "bob-bank-queue-row" });
    const label = bankCardAppend(line, "label", { class: "bob-bank-queue-row-label" });
    const checkbox = bankCardAppend(label, "input", {
      type: "checkbox",
      "aria-label": `Acknowledge ${row.payee} on ${row.date}`,
    });
    const cents = bankFormatCents(row.cents) || "—";
    bankCardAppend(label, "span", { class: "bob-bank-money" }, cents);
    bankCardAppend(label, "span", { class: "bob-bank-queue-payee" }, row.payee);
    if (row.category) bankCardAppend(label, "span", { class: "bob-bank-queue-category" }, row.category);
    const jump = this.bankCardButton(line, `Open ${row.payee} on ${row.date}`, `Line ${row.line}`,
      () => this.bankCardNavigateRow(row), { class: "bob-bank-row-link" });
    bankCardListen(checkbox, "change", async () => {
      if (!checkbox.checked || view.unloaded) return;
      checkbox.disabled = true;
      let result = null;
      try {
        if (row.id) {
          result = await this.bankApi().ackIds([row.id], { label: row.date });
        } else {
          result = await this.bankCardToggleIdLessRow(row);
        }
      } catch (error) {
        result = { ok: false };
      }
      if (!result || result.ok !== true) {
        checkbox.checked = false;
        checkbox.disabled = false;
        if (result && result.reason === "stale-snapshot") new Notice("Bank row changed. Refresh the queue and try again.");
      }
    });
    if (jump) bankCardSetData(jump, "line", row.line);
  }

  bankCardRenderQueueFooter(root, view, model) {
    const footer = bankCardAppend(root, "footer", { class: "bob-bank-card-footer bob-bank-queue-footer" });
    bankCardAppend(footer, "p", { class: "bob-bank-import-command" }, "Weekly import: bob bank import ~/Downloads/*.qfx");
    const months = bankCardAppend(footer, "div", { class: "bob-bank-recent-months", "aria-label": "Recent bank months" });
    bankCardAppend(months, "span", { class: "bob-bank-section-label" }, "Recent months");
    for (const entry of model.recentMonths) {
      const out = entry.outCents === null
        ? entry.error ? "Out unavailable" : "Out loading"
        : `Out ${bankCardDisplayCents(entry.outCents) || "—"}${entry.stale ? " · updating" : ""}`;
      const link = this.bankCardOpenNoteLink(months, `${entry.month} · ${out}`, entry.path, view.sourcePath);
      if (link && entry.error) link.setAttribute("title", bankErrorModel(entry.error).hint);
    }
    if (model.recentMonths.length === 0) bankCardAppend(months, "span", { class: "bob-bank-footer-muted" }, "No bank month notes yet");
  }

  bankCardHasHub() {
    try {
      const vault = this.app && this.app.vault;
      if (vault && typeof vault.getAbstractFileByPath === "function" && vault.getAbstractFileByPath("bank.md")) return true;
      return this.bankCardMonthPaths().some((entry) => entry.path === "bank.md");
    } catch (error) {
      return false;
    }
  }

  bankCardOpenNoteLink(parent, label, path, sourcePath) {
    const note = String(path || "").replace(/\.md$/i, "");
    const link = bankCardAppend(parent, "a", {
      class: "bob-bank-note-link",
      href: `#${encodeURIComponent(note)}`,
      "aria-label": label,
    }, label);
    bankCardListen(link, "click", (event) => {
      if (event && typeof event.preventDefault === "function") event.preventDefault();
      const workspace = this.app && this.app.workspace;
      try {
        if (workspace && typeof workspace.openLinkText === "function") {
          void workspace.openLinkText(note, sourcePath || "", false);
          return;
        }
        const file = this.app && this.app.vault && this.app.vault.getAbstractFileByPath(path);
        const leaf = workspace && typeof workspace.getLeaf === "function" ? workspace.getLeaf(false) : null;
        if (file && leaf && typeof leaf.openFile === "function") void leaf.openFile(file);
      } catch (error) {
        new Notice("Bank note could not be opened.");
      }
    });
    return link;
  }

  async bankCardNavigateDay(path, date) {
    const month = bankMonthFromPath(path);
    const source = month ? await this.bankCardReadSource(path) : null;
    const heading = source === null ? null : bankLocateDayHeading(source, month, date);
    if (!heading) {
      new Notice("Bank day heading is missing. Refresh the note before navigating.");
      return false;
    }
    return this.bankOpenMonthPathAtLine(path, heading.line);
  }

  async bankCardCurrentRow(path, row) {
    const source = await this.bankCardReadSource(path);
    const month = bankMonthFromPath(path);
    if (source === null || !month) return null;
    const heading = bankLocateDayHeading(source, month, row.date);
    const current = bankRecognizeRow(path, source, row.line);
    if (!heading || !current || current.date !== row.date || current.acknowledged || current.cents !== row.cents) return null;
    if (row.id) {
      const expected = bankNormalizeAckId(row.id);
      if (!expected || current.ackId !== expected) return null;
    } else if (current.ackId) {
      return null;
    }
    const token = bankCategoryCurrentToken(path, source, current.line);
    return {
      source,
      current,
      payeeStart: token && token.token && token.token.payeeSpan
        ? token.token.payeeSpan.start
        : 0,
    };
  }

  async bankCardNavigateRow(row) {
    const current = await this.bankCardCurrentRow(row.path, row);
    if (!current) {
      new Notice("Bank row changed or moved. Refresh the card before navigating.");
      return false;
    }
    return this.bankOpenMonthPathAtLine(row.path, current.current.line, current.payeeStart);
  }

  async bankCardAckSnapshot(day) {
    const ids = bankCardDedupeIds(day && day.ids);
    if (!ids.length) return { ok: false, reason: "empty-selection" };
    return this.bankApi().ackIds(ids, { label: day.date, idLess: day.idLess });
  }

  async bankCardToggleIdLessRow(row) {
    const current = await this.bankCardCurrentRow(row.path, row);
    if (!current) return { ok: false, reason: "stale-snapshot" };
    const opened = await this.bankOpenMonthPathAtLine(row.path, current.current.line);
    if (!opened || this.bankActiveFilePath() !== row.path) return { ok: false, reason: "open-failed" };
    const editor = this.bankActiveEditor();
    if (!editor || typeof editor.getLine !== "function") return { ok: false, reason: "editor-unavailable" };
    const expected = current.current.spans && current.current.spans.line && current.current.spans.line.text;
    if (editor.getLine(current.current.line - 1) !== expected) return { ok: false, reason: "stale-snapshot" };
    return this.bankApi().toggleIdLessRowAtCursor(editor, expected);
  }
}
// ---- src/241n-plugin-bank-badge-model.js ----
// The Bank Badge is a read-only projection of one bob bank report. Keep its
// visibility, copy, tone, tooltip, and target decisions in this pure model so
// every host paints the same contract.

const BANK_BADGE_MONTHS = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

function bankBadgeDate(value, includeYear = false, periodEnd = null) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return "";
  const [year, month, day] = value.split("-").map(Number);
  if (month < 1 || month > 12 || day < 1 || day > 31) return "";
  const endYear = typeof periodEnd === "string" && /^\d{4}-/.test(periodEnd)
    ? Number(periodEnd.slice(0, 4))
    : null;
  const withYear = includeYear || (endYear !== null && year !== endYear);
  return `${BANK_BADGE_MONTHS[month - 1]} ${day}${withYear ? `, ${year}` : ""}`;
}

function bankBadgeKind(reportKind) {
  return ({ day: "day", week: "week", quarter: "quarter", year: "iso_year", all: "all_time" })[reportKind] || null;
}

function bankBadgeAmount(cents, kind) {
  if (!Number.isSafeInteger(cents)) return "";
  const magnitude = Math.abs(cents);
  if (kind === "day" || kind === "week" || magnitude < 100) {
    const dollars = Math.floor(magnitude / 100);
    const remainder = magnitude % 100;
    return `$${bankGroupThousands(dollars)}.${String(remainder).padStart(2, "0")}`;
  }
  const dollars = Math.floor((magnitude + 50) / 100);
  return `$${bankGroupThousands(dollars)}`;
}

function bankBadgeCoverageText(report, kind, today) {
  const coverage = report && report.coverage;
  const period = report && report.period;
  if (!coverage || !period) return "";
  const periodStart = typeof period.start === "string" ? period.start : "";
  const periodEnd = typeof period.end === "string" ? period.end : "";
  const parts = [];
  if (kind === "all") {
    const since = bankBadgeDate(periodStart, true, periodEnd);
    if (since) parts.push(`since ${since}`);
  } else if (typeof coverage.start === "string" && periodStart && coverage.start > periodStart) {
    const since = bankBadgeDate(coverage.start, false, periodEnd);
    if (since) parts.push(`since ${since}`);
  }
  if (
    periodEnd && typeof today === "string" && periodEnd < today &&
    typeof coverage.through === "string" && coverage.through < periodEnd
  ) {
    const through = bankBadgeDate(coverage.through, false, periodEnd);
    if (through) parts.push(`to ${through}`);
  }
  return parts.join(" · ");
}

function bankBadgeMoneyText(cents, explicitPlus = false) {
  if (!Number.isSafeInteger(cents)) return "";
  const text = bankFormatCents(Math.abs(cents));
  if (!text) return "";
  return explicitPlus ? `+${text.replace(/^\+/, "")}` : text.replace(/^\+/, "");
}

function bankBadgeLocation(value) {
  return value && typeof value.path === "string" && value.path &&
    Number.isInteger(value.line) && value.line > 0 &&
    typeof value.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value.date)
    ? { path: value.path, line: value.line, date: value.date }
    : null;
}

function bankBadgeTarget(report, context) {
  const kind = context.kind;
  const navigation = report.navigation && typeof report.navigation === "object"
    ? report.navigation
    : null;
  const waiting = navigation && bankBadgeLocation(navigation.waiting);
  if (waiting) return { ...waiting, type: "waiting" };

  const first = navigation && bankBadgeLocation(navigation.first);
  if (first && (kind === "day" || kind === "week" || (Array.isArray(navigation.months) && navigation.months.length === 1))) {
    return { ...first, type: "day" };
  }

  // Older bob versions have no navigation object. Their day report still
  // identifies the note and heading that the daily strip describes.
  if (!navigation && kind === "day") {
    const day = (Array.isArray(report.days) ? report.days : []).find((entry) => entry && entry.date === context.day);
    if (day && typeof day.path === "string" && day.path && Number.isInteger(day.line) && day.line > 0) {
      return { path: day.path, line: day.line, date: context.day, type: "day" };
    }
  }
  return { path: "bank.md", line: 1, date: null, type: "hub" };
}

function bankBadgeTargetAction(target) {
  if (target && target.type === "waiting") return "Click to open the oldest waiting row (Ctrl+Enter files it)";
  if (target && target.type === "day") {
    const date = bankBadgeDate(target.date, true);
    return `Click to open ${date || target.date} in the bank month note`;
  }
  return "Click to open bank.md";
}

function bankBadgeTooltip(report, context, parts, target) {
  const period = report.period || {};
  const lines = [];
  const label = period.label || period.key || (context.day || "Bank period");
  lines.push(`${label}${period.so_far ? " · so far" : ""}`);

  const inCents = report.totals.in_cents;
  const outCents = report.totals.out_cents;
  if (inCents > 0 || outCents > 0) {
    const net = bankFormatCents(report.totals.net_cents);
    lines.push(`In ${bankBadgeMoneyText(inCents, true)} · Out ${bankBadgeMoneyText(outCents)}${net ? ` · Net ${net}` : ""}`);
  }

  const topOut = (Array.isArray(report.breakdown) ? report.breakdown : [])
    .filter((entry) => entry && Number.isSafeInteger(entry.out_cents) && entry.out_cents > 0)
    .slice()
    .sort((left, right) => right.out_cents - left.out_cents)
    .slice(0, 3);
  if (topOut.length) {
    lines.push(`Top out: ${topOut.map((entry) => `${entry.emoji ? `${entry.emoji} ` : ""}${entry.label} ${bankBadgeMoneyText(entry.out_cents)}`).join(" · ")}`);
  }

  const totals = report.totals;
  const notCounted = [];
  const transfers = Math.max(Number(totals.transfer_out_cents) || 0, Number(totals.transfer_in_cents) || 0);
  if (transfers > 0) notCounted.push(`transfers ↔ ${bankBadgeMoneyText(transfers)}`);
  if (totals.unclassified_in_cents > 0) notCounted.push(`unclassified in ${bankBadgeMoneyText(totals.unclassified_in_cents, true)}`);
  if (totals.cash_traced_cents > 0) notCounted.push(`cash traced ${bankBadgeMoneyText(totals.cash_traced_cents)}`);
  if (notCounted.length) lines.push(`Not counted: ${notCounted.join(" · ")}`);

  const waiting = Number.isInteger(report.waiting.period) ? report.waiting.period : 0;
  if (waiting > 0) {
    const oldest = (report.navigation && report.navigation.waiting && report.navigation.waiting.date) || report.waiting.oldest;
    const oldestText = oldest ? ` · oldest ${bankBadgeDate(oldest, false, period.end) || oldest}` : "";
    const all = context.kind === "day" && context.day === context.today && Number.isInteger(report.waiting.all)
      ? ` · ${report.waiting.all} across all months`
      : "";
    lines.push(`${waiting} ${waiting === 1 ? "row" : "rows"} waiting${oldestText}${all}`);
  }

  if (report.coverage && (report.coverage.tracked_since || report.coverage.imported_through)) {
    const tracked = report.coverage.tracked_since
      ? bankBadgeDate(report.coverage.tracked_since, false, period.end)
      : "";
    const imported = report.coverage.imported_through
      ? bankBadgeDate(report.coverage.imported_through, false, period.end)
      : "";
    const coverage = [];
    if (tracked) coverage.push(`Tracked since ${tracked}`);
    if (imported) coverage.push(`imported through ${imported}`);
    if (coverage.length) lines.push(coverage.join(" · "));
  }

  lines.push(bankBadgeTargetAction(target));
  if (context.stale) {
    lines.push(context.refreshFailed
      ? "Refresh failed; last good values shown."
      : "Values are being refreshed; last good values shown.");
  }
  return lines.join("\n");
}

function bankBadgeAriaLabel(report, context, parts, target) {
  const period = report.period || {};
  const periodLabel = period.label || period.key || context.day || "this period";
  const phrases = [`Bank, ${periodLabel}${period.so_far ? ", so far" : ""}`];
  for (const part of parts) {
    if (part.key === "in" || part.key === "out") phrases.push(`${part.words} ${part.exact}`);
    else if (part.key === "waiting") phrases.push(`${part.amount} ${Number(part.amount) === 1 ? "row" : "rows"} waiting`);
    else if (part.key === "coverage") {
      for (const phrase of part.fragments || []) {
        phrases.push(phrase.startsWith("since ") ? `tracked ${phrase}` : `available ${phrase}`);
      }
    }
  }
  phrases.push(bankBadgeTargetAction(target).replace(/^Click to /, "Opens ").replace(/ \(Ctrl\+Enter files it\)/, ""));
  return phrases.join(": ");
}

function bankBadgeValidDate(value) {
  try {
    if (typeof dayStripDateParts === "function") return dayStripDateParts(value) !== null;
  } catch (error) {
    // Fall through to the pattern check.
  }
  return typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value);
}

function bankBadgeShiftDay(value, amount) {
  try {
    if (typeof dayStripShiftDay === "function") return dayStripShiftDay(value, amount);
  } catch (error) {
    // Fall through to null.
  }
  return "";
}

function bankBadgeExpectedBounds(kind, requestedId) {
  try {
    const id = typeof requestedId === "string" ? requestedId.trim() : "";
    if (!id) return null;
    if (kind === "day") {
      if (!bankBadgeValidDate(id)) return null;
      return { key: id, start: id, end: id };
    }
    if (kind === "week") {
      const match = /^(\d{4})-W(\d{2})$/.exec(id);
      if (!match || typeof periodNotesIsoWeekMonday !== "function") return null;
      const start = periodNotesIsoWeekMonday(Number(match[1]), Number(match[2]));
      if (!start) return null;
      const end = bankBadgeShiftDay(start, 6);
      if (!end) return null;
      return { key: id, start, end };
    }
    if (kind === "quarter") {
      const match = /^(\d{4})-Q([1-4])$/.exec(id);
      if (!match || typeof periodNotesIsoWeekMonday !== "function") return null;
      const year = Number(match[1]);
      const quarter = Number(match[2]);
      const start = periodNotesIsoWeekMonday(year, (quarter - 1) * 13 + 1);
      if (!start) return null;
      const nextStart = quarter < 4
        ? periodNotesIsoWeekMonday(year, quarter * 13 + 1)
        : periodNotesIsoWeekMonday(year + 1, 1);
      if (!nextStart) return null;
      const end = bankBadgeShiftDay(nextStart, -1);
      if (!end) return null;
      return { key: id, start, end };
    }
    if (kind === "year") {
      if (!/^\d{4}$/.test(id) || typeof periodNotesIsoWeekMonday !== "function") return null;
      const year = Number(id);
      const start = periodNotesIsoWeekMonday(year, 1);
      const nextStart = periodNotesIsoWeekMonday(year + 1, 1);
      if (!start || !nextStart) return null;
      const end = bankBadgeShiftDay(nextStart, -1);
      if (!end) return null;
      return { key: id, start, end };
    }
    if (kind === "all") {
      if (id !== "all" && id !== "all_time") return null;
      return { key: "all_time", start: null, end: null };
    }
  } catch (error) {
    return null;
  }
  return null;
}

function bankBadgePeriodIdentityValid(report, ctx) {
  const expectedKind = bankBadgeKind(ctx.kind);
  const period = report && report.period;
  if (!period || expectedKind === null || period.kind !== expectedKind) return false;
  const requestedId = typeof ctx.periodId === "string" && ctx.periodId
    ? ctx.periodId
    : ctx.kind === "day" && typeof ctx.day === "string" && ctx.day
      ? ctx.day
      : null;
  if (ctx.kind === "day") {
    if (!requestedId || !bankBadgeValidDate(requestedId)) return false;
    if (period.start !== requestedId || period.end !== requestedId) return false;
    if (typeof period.key === "string" && period.key && period.key !== requestedId) return false;
    return true;
  }
  if (ctx.kind === "all") {
    if (!requestedId) return false;
    if (period.key !== "all_time") return false;
    if (!bankBadgeValidDate(period.start) || !bankBadgeValidDate(period.end)) return false;
    return true;
  }
  if (!requestedId) return false;
  const expected = bankBadgeExpectedBounds(ctx.kind, requestedId);
  if (!expected) return false;
  if (period.key !== expected.key) return false;
  return period.start === expected.start && period.end === expected.end;
}

function bankBadgeModel(report, context = {}) {
  const ctx = context && typeof context === "object" ? context : {};
  if (report && report.teaching_empty === true) return { state: "hidden", reason: "teaching-empty" };
  if (
    !report || report.command !== "report" || !report.period || !report.totals || !report.waiting ||
    !Number.isSafeInteger(report.totals.in_cents) || report.totals.in_cents < 0 ||
    !Number.isSafeInteger(report.totals.out_cents) || report.totals.out_cents < 0 ||
    !Number.isInteger(report.waiting.period) || report.waiting.period < 0
  ) {
    return { state: "unavailable", reason: "invalid-report", hint: "The bank report could not be read." };
  }
  if (!bankBadgePeriodIdentityValid(report, ctx)) {
    return { state: "unavailable", reason: "period-mismatch", hint: "The bank report does not match this stats strip." };
  }
  const today = typeof ctx.today === "string" ? ctx.today : "";
  const future = (ctx.kind === "day" && typeof ctx.day === "string" && today && ctx.day > today) ||
    (typeof report.period.start === "string" && today && report.period.start > today);
  if (future) return { state: "hidden", reason: "future" };

  const inCents = report.totals.in_cents;
  const outCents = report.totals.out_cents;
  const waiting = report.waiting.period;
  if (inCents === 0 && outCents === 0 && waiting === 0) return { state: "hidden", reason: "empty" };

  const parts = [];
  if (inCents > 0) {
    const amount = bankBadgeAmount(inCents, ctx.kind);
    parts.push({ key: "in", words: "in", amount: `+${amount}`, exact: bankBadgeMoneyText(inCents, true) });
  }
  if (outCents > 0) {
    const amount = bankBadgeAmount(outCents, ctx.kind);
    parts.push({ key: "out", words: "out", amount, exact: bankBadgeMoneyText(outCents) });
  }
  if (waiting > 0) {
    parts.push({
      key: "waiting",
      words: "waiting",
      amount: String(waiting),
      exact: String(waiting),
      amountFirst: true,
    });
  }
  const coverageText = bankBadgeCoverageText(report, ctx.kind, today);
  if (coverageText) {
    const fragments = coverageText.split(" · ");
    for (const fragment of fragments) {
      const space = fragment.indexOf(" ");
      parts.push({
        key: "coverage",
        words: space < 0 ? fragment : fragment.slice(0, space),
        amount: space < 0 ? "" : fragment.slice(space + 1),
        exact: fragment,
        fragments: [fragment],
      });
    }
  }

  const tone = inCents === 0 && outCents === 0 ? "waiting" : inCents > outCents ? "surplus" : "neutral";
  const target = bankBadgeTarget(report, ctx);
  const text = ["BANK", ...parts.map((part) => part.amountFirst
    ? `${part.amount} ${part.words}`
    : [part.words, part.amount].filter(Boolean).join(" "))].join(" · ");
  return {
    state: "badge",
    label: "BANK",
    kind: ctx.kind,
    tone,
    parts,
    text,
    ariaLabel: bankBadgeAriaLabel(report, ctx, parts, target),
    tooltip: bankBadgeTooltip(report, ctx, parts, target),
    target,
    stale: ctx.stale === true,
  };
}
