    self,
    crumbs: collapsed,
    fullLength: crumbs.length,
    truncated: truncated || ownerWalk.truncated || collapsed.length !== crumbs.length,
    broken: broken || ownerWalk.broken,
    cyclic: cyclic || ownerWalk.cyclic,
