  blocksNavApi() {
    try {
      const api = this.dependencyNavApi();
      const blocks = api && api.blocks;
      if (blocks && typeof blocks === "object" && Number(blocks.version) >= 1) {
        return blocks;
      }
      return null;
    } catch (error) {
      return null;
    }
  }

