// ---- src/320-plan-lane-and-config.js ----

// --- Plan lane counter ----------------------------------------------------
// A lane task is a `#task` line the native Tasks engine matches with the
// NEXT or PENDING query in docs/plan.md. This mirrors that predicate over
// Tasks-plugin task objects (tolerant of the shapes Tasks and dataview
// expose).

function planTaskDescription(task) {
  if (!task || typeof task !== "object") {
    return null;
  }
  for (const key of ["description", "text"]) {
    if (typeof task[key] === "string") {
      return task[key];
    }
  }
  return null;
}

function planTaskIsDone(task) {
  if (!task || typeof task !== "object") {
    return true;
  }
  if (task.done === true) {
    return true;
  }
  const type = task.status && task.status.type;
  if (type === "DONE" || type === "CANCELLED" || type === "NON_TASK") {
    return true;
  }
  const name = task.status && task.status.name;
  if (typeof name === "string" && /^(done|cancelled?)\s*$/i.test(name.trim())) {
    return true;
  }
  return false;
}

function planTaskIsBlocked(task, all) {
  if (!task || typeof task !== "object") {
    return false;
  }
  if (typeof task.isBlocked === "function") {
    try {
      return Boolean(task.isBlocked(all));
    } catch (error) {
      return false;
    }
  }
  return task.isBlocked === true || task.blocked === true;
}

function planTaskPath(task) {
  if (!task || typeof task !== "object") {
    return "";
  }
  if (typeof task.path === "string") {
    return task.path;
  }
  if (task.file && typeof task.file.path === "string") {
    return task.file.path;
  }
  return "";
}

function planDayNumber(value) {
  const date = planCoerceDate(value);
  if (!date) {
    return null;
  }
  return (
    date.getFullYear() * 10000 +
    (date.getMonth() + 1) * 100 +
    date.getDate()
  );
}

function planCoerceDate(value) {
  if (value === null || value === undefined) {
    return null;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }
  if (typeof value === "string") {
    const dateOnly = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value.trim());
    if (dateOnly) {
      const year = Number(dateOnly[1]);
      const month = Number(dateOnly[2]);
      const day = Number(dateOnly[3]);
      const date = new Date(year, month - 1, day);
      if (
        date.getFullYear() !== year ||
        date.getMonth() !== month - 1 ||
        date.getDate() !== day
      ) {
        return null;
      }
      return date;
    }
  }
  if (typeof value === "string" || typeof value === "number") {
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
  }
  if (typeof value === "object") {
    if (typeof value.isSameOrBefore === "function") {
      // A moment-like object.
      if (typeof value.year === "function") {
        const date = new Date(
          value.year(),
          (typeof value.month === "function" ? value.month() : 0) || 0,
          (typeof value.date === "function" ? value.date() : 1) || 1,
        );
        return Number.isNaN(date.getTime()) ? null : date;
      }
      if (typeof value.toDate === "function") {
        try {
          return planCoerceDate(value.toDate());
        } catch (error) {
          return null;
        }
      }
      if (typeof value.format === "function") {
        try {
          return planCoerceDate(value.format("YYYY-MM-DD"));
        } catch (error) {
          return null;
        }
      }
      return null;
    }
    if ("moment" in value) {
      return planCoerceDate(value.moment);
    }
    if (value instanceof Date) {
      return planCoerceDate(value);
    }
  }
  return null;
}

function planTaskScheduledDay(task) {
  if (!task || typeof task !== "object") {
    return null;
  }
  for (const key of ["scheduledDate", "scheduled", "scheduledDay"]) {
    if (task[key] !== undefined && task[key] !== null) {
      const day = planDayNumber(task[key]);
      if (day !== null) {
        return day;
      }
    }
  }
  return null;
}

function planTaskTags(task) {
  if (!task || typeof task !== "object" || !Array.isArray(task.tags)) {
    return [];
  }
  return task.tags.filter((tag) => typeof tag === "string");
}

// --- Plan config ----------------------------------------------------------

function planRequireOptionalNodeModule(name) {
  try {
    if (typeof require !== "function") {
      return null;
    }
    return require(name);
  } catch (error) {
    return null;
  }
}

function planJoinPathSegments(firstSegment, ...restSegments) {
  const trim = (text, side) => {
    const value = String(text || "");
    if (side === "left") {
      return value.replace(/^\/+/, "");
    }
    if (side === "right") {
      return value.replace(/\/+$/, "");
    }
    return value.replace(/^\/+|\/+$/g, "");
  };
  const first = trim(firstSegment, "right");
  const rest = restSegments
    .map((segment) => trim(segment, "both"))
    .filter((segment) => segment.length > 0);
  return [first, ...rest].filter((segment) => segment.length > 0).join("/");
}

function planConfigHomeDir(osModule, env) {
  if (osModule && typeof osModule.homedir === "function") {
    try {
      const home = osModule.homedir();
      if (typeof home === "string" && home.trim()) {
        return home;
      }
    } catch (error) {
      // Fall through to $HOME below.
    }
  }
  if (env && typeof env.HOME === "string" && env.HOME.trim()) {
    return env.HOME;
  }
  return "~";
}

function planConfigPath(options = {}) {
  const env =
    options.env ||
    (typeof process !== "undefined" && process.env ? process.env : {});
  const osModule =
    options.osModule === undefined
      ? planRequireOptionalNodeModule("os")
      : options.osModule;
  const xdgConfigHome =
    typeof env.XDG_CONFIG_HOME === "string" && env.XDG_CONFIG_HOME.trim()
      ? env.XDG_CONFIG_HOME
      : null;
  const configHome =
    xdgConfigHome ||
    planJoinPathSegments(planConfigHomeDir(osModule, env), ".config");
  return planJoinPathSegments(configHome, PLAN_CONFIG_RELATIVE_PATH);
}

// Stat cache for `loadPlanCaps`: `{ key, result }`, where the key is the
// config path plus the file's mtime/size (or `"missing"` when the file
// does not exist). The file is reparsed only when the key changes, so the
// 13+ callers never re-read it per call. Creation, deletion, invalid
// edits and recovery, and env path overrides all change the key, so the
// next call re-reads. Callers without a `statSync` (including the unit
// test stubs) read through uncached, exactly as before.
let planCapsStatCache = { key: null, result: null };

function resetPlanCapsCache() {
  planCapsStatCache = { key: null, result: null };
}

function planCapsStatKey(fsModule, configPath) {
  try {
    if (!fsModule || typeof fsModule.statSync !== "function") {
      return null;
    }
    const stat = fsModule.statSync(configPath);
    const mtime =
      stat && stat.mtimeMs !== undefined && stat.mtimeMs !== null
        ? stat.mtimeMs
        : stat && stat.mtime
          ? Number(stat.mtime)
          : "?";
    const size =
      stat && stat.size !== undefined && stat.size !== null ? stat.size : "?";
    return `${mtime}:${size}`;
  } catch (error) {
    if (error && error.code === "ENOENT") {
      return "missing";
    }
    return null;
  }
}

// Where the default per-note cap came from: an explicit
// `plan.max_ready_per_note` (`config`) or the built-in default
// (`default`). Presence only — an invalid value still reads `config`
// (with `invalid: true` beside it), matching the Rust contract.
function planDefaultCapSource(block) {
  const raw =
    block && typeof block === "object" && !Array.isArray(block) ? block : {};
  for (const key of ["max_ready_per_note", "maxReadyPerNote"]) {
    if (raw[key] !== undefined && raw[key] !== null) {
      return "config";
    }
  }
  return "default";
}

// Read `plan:` from `~/.config/bob/config.yml` (honoring XDG_CONFIG_HOME).
// Mobile (no desktop `fs`) and read errors fall back to the defaults.
// Returns `{ caps, invalid, defaultSource, configPath }`; `invalid` is
// true only when the file was read but held a present-but-bad value.
function loadPlanCaps(options = {}) {
  const defaults = defaultPlanCaps();
  const configPath = options.configPath || planConfigPath(options);
  const platform = options.Platform === undefined ? Platform : options.Platform;
  if (platform && platform.isDesktopApp === false) {
    return {
      caps: defaults,
      invalid: false,
      defaultSource: "default",
      configPath,
    };
  }
  const fsModule =
    options.fsModule === undefined
      ? planRequireOptionalNodeModule("fs")
      : options.fsModule;
  if (!fsModule || typeof fsModule.readFileSync !== "function") {
    return {
      caps: defaults,
      invalid: false,
      defaultSource: "default",
      configPath,
    };
  }
  const yamlParser =
    options.parseYaml === undefined ? parseYaml : options.parseYaml;
  if (typeof yamlParser !== "function") {
    return {
      caps: defaults,
      invalid: false,
      defaultSource: "default",
      configPath,
    };
  }
  const statKey = planCapsStatKey(fsModule, configPath);
  const cacheKey =
    statKey === null ? null : `${configPath}\n${statKey}`;
  if (
    cacheKey !== null &&
    planCapsStatCache.key === cacheKey &&
    planCapsStatCache.result
  ) {
    return planCapsStatCache.result;
  }
  const readUncached = () => {
    let rawConfig;
    try {
      rawConfig = fsModule.readFileSync(configPath, "utf8");
    } catch (error) {
      return {
        caps: defaults,
        invalid: Boolean(error && error.code && error.code !== "ENOENT"),
        defaultSource: "default",
        configPath,
      };
    }
    let parsed;
    try {
      parsed = yamlParser(rawConfig);
    } catch (error) {
      return {
        caps: defaults,
        invalid: true,
        defaultSource: "default",
        configPath,
      };
    }
    const block = planCapsBlock(parsed);
    const coerced = coercePlanCaps(block);
    return {
      caps: coerced.caps,
      invalid: coerced.invalid,
      defaultSource: planDefaultCapSource(block),
      configPath,
    };
  };
  const result = readUncached();
  if (cacheKey !== null) {
    planCapsStatCache = { key: cacheKey, result };
  }
  return result;
}

// Keep-moving marks share the cycler's two opt-out keys and successor-label
// catalog. Parse one config snapshot and cache it by the same stat contract as
// plan caps; missing, unreadable, and invalid values retain the safe defaults.
let keepMovingMarkConfigStatCache = { key: null, result: null };

function resetKeepMovingMarkConfigCache() {
  keepMovingMarkConfigStatCache = { key: null, result: null };
}

function keepMovingMarkConfigBoolean(value) {
  if (value === true || value === false) return value;
  if (typeof value === "string") {
    const normalized = value.replace(/["']/g, "").split("#")[0].trim().toLowerCase();
    if (normalized === "true") return true;
    if (normalized === "false") return false;
  }
  return true;
}

function loadKeepMovingMarkConfig(options = {}) {
  const configPath = options.configPath || planConfigPath(options);
  const defaults = {
    keepMoving: true,
    linkUnblocked: true,
    successorLabels: [],
    configPath,
  };
  const platform = options.Platform === undefined ? Platform : options.Platform;
  if (platform && platform.isDesktopApp === false) return defaults;
  const fsModule = options.fsModule === undefined
    ? planRequireOptionalNodeModule("fs")
    : options.fsModule;
  if (!fsModule || typeof fsModule.readFileSync !== "function") return defaults;
  const yamlParser = options.parseYaml === undefined ? parseYaml : options.parseYaml;
  if (typeof yamlParser !== "function") return defaults;
  const statKey = planCapsStatKey(fsModule, configPath);
  const cacheKey = statKey === null ? null : String(configPath) + "\n" + String(statKey);
  if (cacheKey !== null && keepMovingMarkConfigStatCache.key === cacheKey &&
      keepMovingMarkConfigStatCache.result) {
    return keepMovingMarkConfigStatCache.result;
  }
  let result = defaults;
  try {
    const parsed = yamlParser(fsModule.readFileSync(configPath, "utf8"));
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const plan = parsed.plan && typeof parsed.plan === "object" ? parsed.plan : {};
      const relations = parsed.relations && typeof parsed.relations === "object"
        ? parsed.relations
        : {};
      const rawLabels = relations.successor_labels;
      const successorLabels = Array.isArray(rawLabels)
        ? rawLabels.filter((label) => typeof label === "string" && label.trim())
          .map((label) => label.trim())
        : [];
      result = {
        keepMoving: keepMovingMarkConfigBoolean(plan.keep_moving),
        linkUnblocked: keepMovingMarkConfigBoolean(plan.link_unblocked),
        successorLabels,
        configPath,
      };
    }
  } catch (error) {
    result = defaults;
  }
  if (cacheKey !== null) keepMovingMarkConfigStatCache = { key: cacheKey, result };
  return result;
}

// ---- src/330-note-ready-model.js ----
// One shared frontmatter reader for every per-note frontmatter lookup.
// `pathOrFile` is a vault-relative path string or a TFile. It resolves a
// TFile through `vault.getAbstractFileByPath` and reads
// `metadataCache.getFileCache(file)` — the only call that returns a cache
// entry in Obsidian. (Fixes bob-cli-3e: the old `getCache({path})` /
// `getCache(file)` calls always returned null, so per-note overrides
// never applied.) Returns the frontmatter object or null. Never throws.
function noteFrontmatterFor(app, pathOrFile) {
  try {
    const vault = app && app.vault;
    const metadataCache = app && app.metadataCache;
    if (
      !vault ||
      !metadataCache ||
      typeof metadataCache.getFileCache !== "function"
    ) {
      return null;
    }
    let file = null;
    if (typeof pathOrFile === "string") {
      if (typeof vault.getAbstractFileByPath !== "function") {
        return null;
      }
      file = vault.getAbstractFileByPath(pathOrFile);
    } else if (
      pathOrFile &&
      typeof pathOrFile === "object" &&
      typeof pathOrFile.path === "string"
    ) {
      file = pathOrFile;
    }
    if (!file) {
      return null;
    }
    const cache = metadataCache.getFileCache(file);
    const frontmatter =
      cache && typeof cache === "object" ? cache.frontmatter : null;
    return frontmatter &&
      typeof frontmatter === "object" &&
      !Array.isArray(frontmatter)
      ? frontmatter
      : null;
  } catch (error) {
    return null;
  }
}

// --- Per-note Ready cap (api.noteReady v1) --------------------------------
// Shared read-time contract (`docs/plan.md`, "Ready cap per note" in
// bob-cli): one implementation here serves the dash chip, crowded.md,
// and the `## Tasks` heading chips. Field names match the CLI JSON.
// Pure unless noted; the plugin snapshot builder below is the only
// impure part.

const NOTE_READY_DEFAULT_CAP = 5;
const NOTE_READY_CAP_MAX = 999;
const NOTE_READY_DASH_PATH = "dash.md";
const LINT_NOTE_READY_CAP_INVALID = "note_ready_cap_invalid";
const LINT_NOTE_READY_IN_TERMINAL_PROJECT =
  "note_ready_in_terminal_project";

// Directory names whose subtrees never hold per-note entries. Mirrors
// the Rust walk (`is_excluded_directory` plus the `done/` rule); the
// check applies to directory segments only, so `x/done.md` is fine.
// `done/` archives match only as the first path segment, per the shared
// done/ path contract, so `projects/done/` stays a live note.
const NOTE_READY_EXCLUDED_DIRS = [
  ".git",
  ".obsidian",
  "_templates",
  "_conflicts",
  "_generated",
];

function noteReadyPathExcluded(path) {
  const text = String(path || "");
  if (!text) {
    return true;
  }
  if (text === NOTE_READY_DASH_PATH) {
    return true;
  }
  if (isDoneArchivePath(text)) {
    return true;
  }
  const segments = text.split("/");
  for (let index = 0; index < segments.length - 1; index += 1) {
    if (NOTE_READY_EXCLUDED_DIRS.includes(segments[index])) {
      return true;
    }
  }
  return false;
}

function noteReadyStemForPath(path) {
  const text = String(path || "");
  const slash = text.lastIndexOf("/");
  const base = slash === -1 ? text : text.slice(slash + 1);
  return base.toLowerCase().endsWith(".md")
    ? base.slice(0, -3)
    : base;
}

function noteReadyStripQuotes(text) {
  const value = String(text || "").trim();
  if (value.length >= 2) {
    const first = value[0];
    const last = value[value.length - 1];
    if (
      (first === '"' && last === '"') ||
      (first === "'" && last === "'")
    ) {
      return value.slice(1, -1).trim();
    }
  }
  return value;
}

// One scalar `type` value to a kind. Accepts `[[project]]` /
// `[[area]]` exactly, plus the inner word that bare YAML wikilinks
// parse to (`[["project"]]` arrives as a nested array; `"project"`
// survives inside flow lists).
function noteReadyScalarKind(value) {
  const text = noteReadyStripQuotes(value);
  if (!text) {
    return null;
  }
  if (text === "[[project]]") {
    return "project";
  }
  if (text === "[[area]]") {
    return "area";
  }
  const inner = text
    .replace(/^[[ '"\]]+|[[ '"\]]+$/g, "")
    .trim();
  if (inner === "project") {
    return "project";
  }
  if (inner === "area") {
    return "area";
  }
  return null;
}

// A parsed `type` frontmatter value (string, array, or the nested
// `[["project"]]` array bare YAML wikilinks parse to) to
// `area`|`project`|null. Area wins ties, as in Rust.
function noteReadyKindFromType(value) {
  const fromScalarList = (text) => {
    const trimmed = String(text || "").trim();
    if (!trimmed) {
      return null;
    }
    if (trimmed.startsWith("[")) {
      const inner = trimmed.endsWith("]")
        ? trimmed.slice(1, -1)
        : trimmed.slice(1);
      let project = null;
      for (const item of inner.split(",")) {
        const kind = noteReadyScalarKind(item);
        if (kind === "area") {
          return "area";
        }
        if (kind === "project") {
          project = "project";
        }
      }
      return project;
    }
    return noteReadyScalarKind(trimmed);
  };
  if (typeof value === "string") {
    return fromScalarList(value);
  }
  if (Array.isArray(value)) {
    let project = null;
    for (const item of value) {
      if (typeof item === "string") {
        const kind = fromScalarList(item);
        if (kind === "area") {
          return "area";
        }
        if (kind === "project") {
          project = "project";
        }
      } else if (Array.isArray(item)) {
        for (const nested of item) {
          if (typeof nested !== "string") {
            continue;
          }
          const kind = noteReadyScalarKind(nested);
          if (kind === "area") {
            return "area";
          }
          if (kind === "project") {
            project = "project";
          }
        }
      }
    }
    return project;
  }
  return null;
}

// Parsed `status` frontmatter to a label: `wip`, `waiting`, `done`,
// `canceled`, or the lowercased value. Mirrors `ProjectStatus::parse`.
function noteReadyStatusLabel(value) {
  let text = "";
  if (typeof value === "string") {
    text = value;
  } else if (value !== undefined && value !== null) {
    text = String(value);
  }
  const normalized = noteReadyStripQuotes(text).toLowerCase();
  if (normalized === "" || normalized === "wip") {
    return "wip";
  }
  if (normalized === "waiting") {
    return "waiting";
  }
  if (normalized === "done") {
    return "done";
  }
  if (normalized === "canceled" || normalized === "cancelled") {
    return "canceled";
  }
  return normalized;
}

function noteReadyStatusIsTerminal(statusLabel) {
  return statusLabel === "done" || statusLabel === "canceled";
}

// Parsed `parent` frontmatter to a stem. Mirrors the Rust
// `wikilink_target` (alias/heading stripped, last path segment, and
// lowercased, since Rust stores the link name).
function noteReadyParentStem(value) {
  if (typeof value !== "string") {
    return null;
  }
  const text = noteReadyStripQuotes(value);
  if (!text.startsWith("[[") || !text.endsWith("]]")) {
    return null;
  }
  let inner = text.slice(2, -2).trim();
  const pipe = inner.indexOf("|");
  if (pipe !== -1) {
    inner = inner.slice(0, pipe);
  }
  const hash = inner.indexOf("#");
  if (hash !== -1) {
    inner = inner.slice(0, hash);
  }
  const slash = inner.lastIndexOf("/");
  if (slash !== -1) {
    inner = inner.slice(slash + 1);
  }
  inner = inner.trim();
  if (!inner) {
    return null;
  }
  return inner.toLowerCase();
}

// Parse a raw `ready_cap` frontmatter value (number, digit string,
// `off` in any case, or boolean `false` for exempt). Returns
// `{ cap, source, exempt, invalid }`: `cap` is null for exempt notes;
// `invalid` means present-but-bad, and the caller falls back to the
// default and emits `note_ready_cap_invalid`. Mirrors the Rust
// `parse_ready_cap`.
function parseNoteReadyCap(raw, defaultCap, defaultSource) {
  const fallback = {
    cap: defaultCap,
    source: defaultSource,
    exempt: false,
    invalid: false,
  };
  if (raw === undefined || raw === null) {
    return fallback;
  }
  if (typeof raw === "boolean") {
    if (raw === false) {
      return { cap: null, source: "note", exempt: true, invalid: false };
    }
    return { ...fallback, invalid: true };
  }
  if (typeof raw === "number") {
    if (
      Number.isInteger(raw) &&
      raw >= 1 &&
      raw <= NOTE_READY_CAP_MAX
    ) {
      return { cap: raw, source: "note", exempt: false, invalid: false };
    }
    return { ...fallback, invalid: true };
  }
  if (typeof raw === "string") {
    const text = noteReadyStripQuotes(raw);
    if (!text) {
      return fallback;
    }
    const lowered = text.toLowerCase();
    if (lowered === "off" || lowered === "false") {
      return { cap: null, source: "note", exempt: true, invalid: false };
    }
    if (/^[+-]?\d+$/.test(text)) {
      const number = Number(text);
      if (
        Number.isSafeInteger(number) &&
        number >= 1 &&
        number <= NOTE_READY_CAP_MAX
      ) {
        return {
          cap: number,
          source: "note",
          exempt: false,
          invalid: false,
        };
      }
    }
    return { ...fallback, invalid: true };
  }
  return { ...fallback, invalid: true };
}

function noteReadyStateRank(state) {
  if (state === "crowded") {
    return 0;
  }
  if (state === "full") {
    return 1;
  }
  if (state === "room") {
    return 2;
  }
  if (state === "empty") {
    return 3;
  }
  return 4;
}

function noteReadyEmptyTotals() {
  return {
    notes: 0,
    areas: 0,
    projects: 0,
    crowded: 0,
    full: 0,
    room: 0,
    empty: 0,
    exempt: 0,
    counted: 0,
    excess: 0,
    recurring: 0,
  };
}

function noteReadyRawLabel(raw) {
  if (typeof raw === "string") {
    return raw.trim();
  }
  try {
    const encoded = JSON.stringify(raw);
    return encoded === undefined ? String(raw) : encoded;
  } catch (error) {
    return String(raw);
  }
}

// Pure per-note Ready evaluation: no I/O, unit-testable. `notes` holds
// typed-note entries
// `{ path, name, kind, status, isArea, isTerminal, parent, ready_cap_raw }`;
// `rows` holds in-lane, non-`prj` rows
// `{ path, recurring, blockId, bucket }` where `bucket` is a freshness
// `"new"`/`"rotten"`/null. Rows whose path matches no note are ignored.
// Terminal projects are never capped: they contribute no entry, and a
// `note_ready_in_terminal_project` lint is emitted once when they still
// hold counted rows. Mirrors the Rust `evaluate`.
function noteReadyEvaluate({
  notes,
  rows,
  defaultCap,
  defaultSource,
  freshnessAvailable,
}) {
  const cap = Number.isInteger(defaultCap) ? defaultCap : NOTE_READY_DEFAULT_CAP;
  const source =
    defaultSource === "config" || defaultSource === "preview"
      ? defaultSource
      : "default";
  const noteList = Array.isArray(notes) ? notes : [];
  const rowList = Array.isArray(rows) ? rows : [];
  const byPath = new Map();
  for (const row of rowList) {
    if (!row || typeof row.path !== "string" || !row.path) {
      continue;
    }
    if (!byPath.has(row.path)) {
      byPath.set(row.path, []);
    }
    byPath.get(row.path).push(row);
  }
  const entries = [];
  const lints = [];
  for (const note of noteList) {
    if (!note || typeof note.path !== "string") {
      continue;
    }
    const noteRows = byPath.get(note.path) || [];
    const countedRows = noteRows.filter((row) => !row.recurring);
    const count = countedRows.length;
    const recurring = noteRows.filter((row) => row.recurring).length;
    if (!note.isArea && note.isTerminal) {
      if (count > 0) {
        lints.push({
          code: LINT_NOTE_READY_IN_TERMINAL_PROJECT,
          path: note.path,
          message:
            `project ${note.name} is ${note.status} but still holds ` +
            `${count} ready ${count === 1 ? "task" : "tasks"}`,
        });
      }
      continue;
    }
    const parsed = parseNoteReadyCap(note.ready_cap_raw, cap, source);
    if (parsed.invalid) {
      lints.push({
        code: LINT_NOTE_READY_CAP_INVALID,
        path: note.path,
        message:
          `ready_cap ${JSON.stringify(noteReadyRawLabel(note.ready_cap_raw))} ` +
          `in ${note.name} is not 1–999 or off; using ${cap}`,
      });
    }
    let state = "empty";
    let overBy = 0;
    let capValue = parsed.cap;
    if (parsed.exempt) {
      state = "exempt";
      capValue = null;
    } else {
      const limit =
        Number.isInteger(capValue) && capValue !== null ? capValue : cap;
      if (count > limit) {
        state = "crowded";
        overBy = count - limit;
      } else if (count === limit) {
        state = "full";
      } else if (count > 0) {
        state = "room";
      } else {
        state = "empty";
      }
    }
    let makeUp = null;
    if (freshnessAvailable) {
      let fresh = 0;
      let rotten = 0;
      for (const row of countedRows) {
        if (row.bucket === "new") {
          fresh += 1;
        } else if (row.bucket === "rotten") {
          rotten += 1;
        }
      }
      makeUp = {
        ready: Math.max(0, count - fresh - rotten),
        new: fresh,
        rotten,
      };
    }
    entries.push({
      path: note.path,
      name: note.name,
      kind: note.kind,
      status: note.status,
      parent: note.parent === undefined ? null : note.parent,
      count,
      cap: capValue,
      cap_source: parsed.source,
      state,
      over_by: overBy,
      make_up: makeUp,
      recurring,
    });
  }
  entries.sort((a, b) => {
    const rank = noteReadyStateRank(a.state) - noteReadyStateRank(b.state);
    if (rank !== 0) {
      return rank;
    }
    if (a.over_by !== b.over_by) {
      return b.over_by - a.over_by;
    }
    if (a.count !== b.count) {
      return b.count - a.count;
    }
    const nameA = String(a.name || "").toLowerCase();
    const nameB = String(b.name || "").toLowerCase();
    if (nameA !== nameB) {
      return nameA < nameB ? -1 : 1;
    }
    return String(a.path) < String(b.path)
      ? -1
      : String(a.path) > String(b.path)
        ? 1
        : 0;
  });
  const totals = noteReadyEmptyTotals();
  for (const entry of entries) {
    totals.recurring += entry.recurring;
    if (entry.state === "exempt") {
      totals.exempt += 1;
      continue;
    }
    totals.notes += 1;
    if (entry.kind === "area") {
      totals.areas += 1;
    } else {
      totals.projects += 1;
    }
    totals.counted += entry.count;
    totals.excess += entry.over_by;
    if (entry.state === "crowded") {
      totals.crowded += 1;
    } else if (entry.state === "full") {
      totals.full += 1;
    } else if (entry.state === "room") {
      totals.room += 1;
    } else if (entry.state === "empty") {
      totals.empty += 1;
    }
  }
  lints.sort((a, b) => {
    if (a.path !== b.path) {
      return String(a.path) < String(b.path) ? -1 : 1;
    }
    return String(a.code) < String(b.code)
      ? -1
      : String(a.code) > String(b.code)
        ? 1
        : 0;
  });
  return { notes: entries, totals, lints };
}

// Recurrence under the `freshnessRowFromTask` rule: a Tasks recurrence,
// flag, or `[repeat:: …]` inline field.
function noteReadyRecurringFor(task) {
  try {
    if (!task || typeof task !== "object") {
      return false;
    }
    if (Boolean(task.recurrence)) {
      return true;
    }
    if (task.isRecurring === true || task.recurring === true) {
      return true;
    }
    const description = planTaskDescription(task);
    const rawLine =
      typeof task.originalMarkdown === "string"
        ? task.originalMarkdown
        : typeof description === "string"
          ? description
          : "";
    return freshnessHasRepeatField(rawLine);
  } catch (error) {
    return false;
  }
}

// Stable key for the crowded set plus caps: the query-refresh trigger
// compares it to detect crowded/cap/label changes that no Tasks cache
// change carries.
function noteReadyCrowdedKey(notes, capsKey) {
  try {
    const crowded = [];
    for (const entry of Array.isArray(notes) ? notes : []) {
      if (entry && entry.state === "crowded") {
        crowded.push([entry.path, entry.count, entry.cap]);
      }
    }
    return JSON.stringify([crowded, capsKey || null]);
  } catch (error) {
    return JSON.stringify(["error", capsKey || null]);
  }
}

// ---- src/340-dashboard-views-and-plan-block.js ----
// --- Dashboard collections (dashboardCollections namespace v1) ------------
// Live PROJECTS / REFERENCES badges for the Dashboard Browse row. Counts
// mirror the pinned default Base views (`projects.base#Active & Waiting`
// and `refs.base#Reading Queue`) without a general Bases interpreter:
// the Base contracts below are validated together with the membership
// predicates, and any membership-affecting drift marks that collection
// unavailable rather than advertising a stale count. All pure helpers
// are unit-testable without Obsidian.

const DASHBOARD_COLLECTIONS_VERSION = 1;
const DASHBOARD_COLLECTION_PROJECTS_VIEW = "🚀 Active & Waiting";
const DASHBOARD_COLLECTION_REFERENCES_VIEW = "🔖 Reading Queue";
const DASHBOARD_COLLECTION_PROJECTS_DEST = "dash_projects";
const DASHBOARD_COLLECTION_REFERENCES_DEST = "dash_references";
const DASHBOARD_COLLECTION_PROJECTS_LABEL = "PROJECTS";
const DASHBOARD_COLLECTION_REFERENCES_LABEL = "REFERENCES";
const DASHBOARD_COLLECTION_ARROW = "↗";

function dashboardCollectionStripQuotes(value) {
  try {
    let text = String(value === null || value === undefined ? "" : value).trim();
    if (text.length >= 2) {
      const first = text[0];
      const last = text[text.length - 1];
      if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
        text = text.slice(1, -1).trim();
      }
    }
    return text;
  } catch (error) {
    return "";
  }
}

function dashboardCollectionLinkTarget(value) {
  try {
    const stripped = dashboardCollectionStripQuotes(value);
    if (!stripped) {
      return "";
    }
    const m = stripped.match(/^\[\[(.+?)\]\]$/);
    let inner = m ? m[1] : stripped;
    inner = String(inner || "").trim();
    if (!inner) {
      return "";
    }
    const pipeAt = inner.indexOf("|");
    if (pipeAt !== -1) {
      inner = inner.slice(0, pipeAt).trim();
    }
    const hashAt = inner.indexOf("#");
    if (hashAt !== -1) {
      inner = inner.slice(0, hashAt).trim();
    }
    return inner;
  } catch (error) {
    return "";
  }
}

// Obsidian Bases `containsAny` semantics: a scalar string uses substring
// matching while a list matches list elements exactly. Anything else
// (missing, number, object) never matches.
function dashboardCollectionStatusContainsAny(statusRaw, needles) {
  try {
    const wants = Array.isArray(needles) ? needles : [];
    if (typeof statusRaw === "string") {
      for (const needle of wants) {
        if (typeof needle === "string" && needle && statusRaw.indexOf(needle) !== -1) {
          return true;
        }
      }
      return false;
    }
    if (Array.isArray(statusRaw)) {
      for (const item of statusRaw) {
        if (typeof item !== "string") {
          continue;
        }
        for (const needle of wants) {
          if (item === needle) {
            return true;
          }
        }
      }
      return false;
    }
    return false;
  } catch (error) {
    return false;
  }
}

function dashboardCollectionPathInTemplates(path) {
  try {
    const parts = String(path || "").split("/");
    for (const part of parts.slice(0, -1)) {
      if (part === "_templates") {
        return true;
      }
    }
    // A root-level `_templates.md` is not a folder match.
    return false;
  } catch (error) {
    return false;
  }
}

// A project note: scalar type link resolving to `project.md` (alias and
// path spellings resolve through the caller-supplied resolver), outside
// any `_templates/` folder, with active/waiting status. A list type or an
// unresolvable type never counts: never widened into link equality.
function dashboardCollectionIsProjectMember(note, resolver) {
  try {
    if (!note || typeof note !== "object") {
      return false;
    }
    const path = typeof note.path === "string" ? note.path : "";
    if (!path || !/\.md$/.test(path)) {
      return false;
    }
    if (dashboardCollectionPathInTemplates(path)) {
      return false;
    }
    const frontmatter =
      note.frontmatter && typeof note.frontmatter === "object" && !Array.isArray(note.frontmatter)
        ? note.frontmatter
        : null;
    if (!frontmatter) {
      return false;
    }
    const typeRaw = frontmatter.type;
    if (typeof typeRaw !== "string") {
      return false;
    }
    const target = dashboardCollectionLinkTarget(typeRaw);
    if (!target) {
      return false;
    }
    let destPath = null;
    try {
      if (typeof resolver === "function") {
        const dest = resolver(target, path);
        if (dest && typeof dest.path === "string") {
          destPath = dest.path;
        } else if (typeof dest === "string") {
          destPath = dest;
        }
      }
    } catch (error) {
      destPath = null;
    }
    if (!destPath) {
      // Fallback for pure unit tests without an Obsidian resolver: an
      // exact `project` / `project.md` target counts. Live code always
      // supplies the resolver above, so this never widens vault reads.
      const lowered = target.toLowerCase();
      if (lowered !== "project" && lowered !== "project.md") {
        return false;
      }
    } else if (destPath !== "project.md") {
      return false;
    }
    return dashboardCollectionStatusContainsAny(frontmatter.status, ["wip", "waiting"]);
  } catch (error) {
    return false;
  }
}

// A reference note: exact `ref/` prefix, Markdown extension, scalar status
// exactly `next`, `wip`, or `ready` (case-sensitive). Lists never count,
// PDFs/`lib/` files, `ref.md`, and similarly named folders never count,
// and no task-only Today/hide/freshness/schedule filters apply.
function dashboardCollectionIsReferenceMember(note) {
  try {
    if (!note || typeof note !== "object") {
      return false;
    }
    const path = typeof note.path === "string" ? note.path : "";
    if (!path || path.indexOf("ref/") !== 0) {
      return false;
    }
    if (!/\.md$/.test(path)) {
      return false;
    }
    const frontmatter =
      note.frontmatter && typeof note.frontmatter === "object" && !Array.isArray(note.frontmatter)
        ? note.frontmatter
        : null;
    if (!frontmatter) {
      return false;
    }
    const status = frontmatter.status;
    return status === "next" || status === "wip" || status === "ready";
  } catch (error) {
    return false;
  }
}

function dashboardCollectionNormalizeFilterText(text) {
  try {
    return String(text === null || text === undefined ? "" : text)
      .replace(/'/g, '"')
      .replace(/\s+/g, "")
      .trim();
  } catch (error) {
    return "";
  }
}

function dashboardCollectionFilterList(value) {
  if (Array.isArray(value)) {
    return value.filter((item) => typeof item === "string");
  }
  if (typeof value === "string") {
    return [value];
  }
  return [];
}

function dashboardCollectionFindView(parsed, name) {
  try {
    const views = parsed && Array.isArray(parsed.views) ? parsed.views : [];
    for (const view of views) {
      if (view && view.name === name) {
        return view;
      }
    }
    return null;
  } catch (error) {
    return null;
  }
}

function dashboardCollectionHasLimit(node) {
  try {
    if (!node || typeof node !== "object") {
      return false;
    }
    for (const key of ["limit", "pagination", "maxResults", "take"]) {
      if (node[key] !== undefined && node[key] !== null) {
        return true;
      }
    }
    return false;
  } catch (error) {
    return false;
  }
}

// Validate the membership-affecting structure of `projects.base`:
// global `note.type == link("project")` plus `_templates` exclusion, and
// the `Active & Waiting` view's `status.containsAny("wip","waiting")`.
// Presentation-only keys (formulas, columns, grouping, sorting) are
// ignored. Any result limit, extra global filter, or renamed view fails
// closed so the badge shows unavailable instead of a stale count.
function dashboardCollectionValidateProjectsBase(parsed) {
  try {
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { ok: false, reason: "projects.base is unreadable" };
    }
    if (dashboardCollectionHasLimit(parsed)) {
      return { ok: false, reason: "projects.base has a result limit" };
    }
    const filters = parsed.filters && typeof parsed.filters === "object" ? parsed.filters : null;
    const globalAnd = filters ? dashboardCollectionFilterList(filters.and) : [];
    if (!filters || !Array.isArray(filters.and) || globalAnd.length !== 2) {
      return { ok: false, reason: "projects.base global filters changed" };
    }
    const normalized = new Set(globalAnd.map(dashboardCollectionNormalizeFilterText));
    const wantA = dashboardCollectionNormalizeFilterText('note.type == link("project")');
    const wantB = dashboardCollectionNormalizeFilterText('file.inFolder("_templates") == false');
    if (!normalized.has(wantA) || !normalized.has(wantB) || normalized.size !== 2) {
      return { ok: false, reason: "projects.base global filters changed" };
    }
    const view = dashboardCollectionFindView(parsed, DASHBOARD_COLLECTION_PROJECTS_VIEW);
    if (!view) {
      return { ok: false, reason: "projects.base Active & Waiting view is missing" };
    }
    if (dashboardCollectionHasLimit(view)) {
      return { ok: false, reason: "projects.base Active & Waiting view has a result limit" };
    }
    const viewFilters = view.filters && typeof view.filters === "object" ? view.filters : null;
    const viewAnd = viewFilters ? dashboardCollectionFilterList(viewFilters.and) : [];
    if (!viewFilters || !Array.isArray(viewFilters.and) || viewAnd.length !== 1) {
      return { ok: false, reason: "projects.base Active & Waiting filters changed" };
    }
    const wantView = dashboardCollectionNormalizeFilterText('status.containsAny("wip", "waiting")');
    if (dashboardCollectionNormalizeFilterText(viewAnd[0]) !== wantView) {
      return { ok: false, reason: "projects.base Active & Waiting filters changed" };
    }
    return { ok: true, reason: null };
  } catch (error) {
    return { ok: false, reason: "projects.base is unreadable" };
  }
}

// Validate the membership-affecting structure of `refs.base`: global
// `ref/` prefix plus Markdown extension, and the Reading Queue view's
// exact `next`/`wip`/`ready` disjunction. Same fail-closed policy.
function dashboardCollectionValidateRefsBase(parsed) {
  try {
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return { ok: false, reason: "refs.base is unreadable" };
    }
    if (dashboardCollectionHasLimit(parsed)) {
      return { ok: false, reason: "refs.base has a result limit" };
    }
    const filters = parsed.filters && typeof parsed.filters === "object" ? parsed.filters : null;
    const globalAnd = filters ? dashboardCollectionFilterList(filters.and) : [];
    if (!filters || !Array.isArray(filters.and) || globalAnd.length !== 2) {
      return { ok: false, reason: "refs.base global filters changed" };
    }
    const normalized = new Set(globalAnd.map(dashboardCollectionNormalizeFilterText));
    const wantA = dashboardCollectionNormalizeFilterText('file.path.startsWith("ref/")');
    const wantB = dashboardCollectionNormalizeFilterText('file.ext == "md"');
    if (!normalized.has(wantA) || !normalized.has(wantB) || normalized.size !== 2) {
      return { ok: false, reason: "refs.base global filters changed" };
    }
    const view = dashboardCollectionFindView(parsed, DASHBOARD_COLLECTION_REFERENCES_VIEW);
    if (!view) {
      return { ok: false, reason: "refs.base Reading Queue view is missing" };
    }
    if (dashboardCollectionHasLimit(view)) {
      return { ok: false, reason: "refs.base Reading Queue view has a result limit" };
    }
    const viewFilters = view.filters && typeof view.filters === "object" ? view.filters : null;
    const viewOr = viewFilters ? dashboardCollectionFilterList(viewFilters.or) : [];
    if (!viewFilters || !Array.isArray(viewFilters.or) || viewOr.length !== 3) {
      return { ok: false, reason: "refs.base Reading Queue filters changed" };
    }
    const normalizedOr = new Set(viewOr.map(dashboardCollectionNormalizeFilterText));
    const wantNext = dashboardCollectionNormalizeFilterText('status == "next"');
    const wantWip = dashboardCollectionNormalizeFilterText('status == "wip"');
    const wantReady = dashboardCollectionNormalizeFilterText('status == "ready"');
    if (!normalizedOr.has(wantNext) || !normalizedOr.has(wantWip) || !normalizedOr.has(wantReady) || normalizedOr.size !== 3) {
      return { ok: false, reason: "refs.base Reading Queue filters changed" };
    }
    return { ok: true, reason: null };
  } catch (error) {
    return { ok: false, reason: "refs.base is unreadable" };
  }
}

function dashboardCollectionEntryFor(kind, count, available, reason) {
  const isProjects = kind === "projects";
  const label = isProjects ? DASHBOARD_COLLECTION_PROJECTS_LABEL : DASHBOARD_COLLECTION_REFERENCES_LABEL;
  const destination = isProjects ? DASHBOARD_COLLECTION_PROJECTS_DEST : DASHBOARD_COLLECTION_REFERENCES_DEST;
  const view = isProjects ? DASHBOARD_COLLECTION_PROJECTS_VIEW : DASHBOARD_COLLECTION_REFERENCES_VIEW;
  const unit = isProjects ? "projects" : "references";
  if (available === true && Number.isInteger(count) && count >= 0) {
    const tooltip = isProjects
      ? `${count} projects in Active & Waiting. Open Projects.`
      : `${count} references in Reading Queue (next, wip, ready). Open References.`;
    return {
      kind: isProjects ? "projects" : "references",
      label,
      count,
      available: true,
      reason: null,
      destination,
      view,
      unit,
      valueText: String(count),
      tooltip,
      aria: tooltip,
      placeholder: false,
      over: false,
    };
  }
  const short = reason ? String(reason) : "unavailable";
  const tooltip = isProjects
    ? `PROJECTS – ${short}. Open Projects.`
    : `REFERENCES – ${short}. Open References.`;
  const aria = isProjects
    ? `PROJECTS unavailable (${short}). Open Projects.`
    : `REFERENCES unavailable (${short}). Open References.`;
  return {
    kind: isProjects ? "projects" : "references",
    label,
    count: null,
    available: false,
    reason: short,
    destination,
    view,
    unit,
    valueText: "–",
    tooltip,
    aria,
    placeholder: true,
    over: false,
  };
}

function dashboardCollectionChipModel(kind, entry) {
  try {
    const normalized = kind === "references" ? "references" : "projects";
    const safe =
      entry && typeof entry === "object"
        ? entry
        : dashboardCollectionEntryFor(normalized, null, false, "unavailable");
    return {
      kind: normalized,
      label: normalized === "projects" ? DASHBOARD_COLLECTION_PROJECTS_LABEL : DASHBOARD_COLLECTION_REFERENCES_LABEL,
      valueText: typeof safe.valueText === "string" ? safe.valueText : "–",
      tooltip: typeof safe.tooltip === "string" ? safe.tooltip : "Unavailable",
      aria: typeof safe.aria === "string" ? safe.aria : "Unavailable",
      destination: typeof safe.destination === "string" ? safe.destination : normalized === "projects" ? DASHBOARD_COLLECTION_PROJECTS_DEST : DASHBOARD_COLLECTION_REFERENCES_DEST,
      placeholder: safe.placeholder === true || safe.available === false,
    };
  } catch (error) {
    const normalized = kind === "references" ? "references" : "projects";
    const fallback = dashboardCollectionEntryFor(normalized, null, false, "unavailable");
    return {
      kind: normalized,
      label: fallback.label,
      valueText: "–",
      tooltip: fallback.tooltip,
      aria: fallback.aria,
      destination: fallback.destination,
      placeholder: true,
    };
  }
}

function dashboardCollectionChipClass(kind, model) {
  const normalized = kind === "references" ? "references" : "projects";
  const unavailable = model && model.placeholder ? " bob-plan-unavailable" : "";
  return `bob-plan-chip bob-plan-${normalized}${unavailable}`;
}

// --- Per-note Ready cap views (ledger-views) ---------------------------
// Pure view models for the dash CROWDED chip, the `bob-ready-notes`
// ranked-bar block, and the `## Tasks` heading chip. All take plain
// snapshot/entry data so they are unit-testable without Obsidian.

const NOTE_READY_CROWDED_LABEL = "CROWDED";
const NOTE_READY_CROWDED_ARROW = "↗";
// First `## Tasks` heading only: up to 3 leading spaces, exactly two
// `#`, at least one space/tab, then `Tasks` case-insensitive with an
// optional trailing run. `### Tasks` never matches (the third `#` is
// not a space); fences are tracked by the line walker below.
const NOTE_READY_TASKS_HEADING_RE = /^ {0,3}##[ \t]+Tasks(?:[ \t].*)?$/i;
const NOTE_READY_FENCE_RE = /^ {0,3}(`{3,}|~{3,})/;
const NOTE_READY_BAR_MAX = 30;
const NOTE_READY_REMEDIES = "split, sequence, defer, or drop";

function noteReadyCapSourceLabel(source) {
  if (source === "note") {
    return "this note";
  }
  if (source === "config") {
    return "Bob config";
  }
  if (source === "preview") {
    return "preview";
  }
  return "default";
}

function noteReadyCrowdedChipModel(snapshot) {
  try {
    if (!snapshot || snapshot.available !== true) {
      return {
        available: false,
        crowded: 0,
        full: 0,
        excess: 0,
        label: NOTE_READY_CROWDED_LABEL,
        valueText: "–",
        over: false,
        calm: false,
        placeholder: true,
        tooltip: "CROWDED unavailable",
        aria: "CROWDED: unavailable",
      };
    }
    const totals = snapshot.totals || {};
    const crowded = Number.isInteger(totals.crowded) ? totals.crowded : 0;
    const full = Number.isInteger(totals.full) ? totals.full : 0;
    const excess = Number.isInteger(totals.excess) ? totals.excess : 0;
    const notes = Array.isArray(snapshot.notes) ? snapshot.notes : [];
    const crowdedNotes = notes.filter(
      (entry) => entry && entry.state === "crowded",
    );
    const named = crowdedNotes
      .slice(0, 5)
      .map((entry) => `${entry.name} ${entry.count}/${entry.cap}`);
    const more = crowdedNotes.length > 5 ? ", …" : "";
    const list = named.length > 0 ? `: ${named.join(", ")}${more}` : "";
    const noun = crowded === 1 ? "note" : "notes";
    const tooltip =
      crowded > 0
        ? `${crowded} ${noun} over their ready cap${list} · ${full} full · ${excess} over. Open Crowded Notes.`
        : `No notes over their ready cap · ${full} full. Open Crowded Notes.`;
    return {
      available: true,
      crowded,
      full,
      excess,
      label: NOTE_READY_CROWDED_LABEL,
      valueText: crowded > 0 ? String(crowded) : "0 ✓",
      over: crowded > 0,
      calm: crowded === 0,
      placeholder: false,
      tooltip,
      aria: tooltip,
    };
  } catch (error) {
    return {
      available: false,
      crowded: 0,
      full: 0,
      excess: 0,
      label: NOTE_READY_CROWDED_LABEL,
      valueText: "–",
      over: false,
      calm: false,
      placeholder: true,
      tooltip: "CROWDED unavailable",
      aria: "CROWDED: unavailable",
    };
  }
}

function noteReadyBarModel(count, cap, max = NOTE_READY_BAR_MAX) {
  const safeMax = Number.isInteger(max) && max > 0 ? max : NOTE_READY_BAR_MAX;
  const safeCount = Number.isInteger(count) && count >= 0 ? count : 0;
  const safeCap =
    Number.isInteger(cap) && cap > 0 ? cap : NOTE_READY_DEFAULT_CAP;
  const total = Math.min(safeMax, Math.max(safeCap, safeCount));
  return {
    total,
    filled: Math.min(safeCount, total),
    capAt: Math.min(safeCap, total),
    overflow: Math.max(0, safeCount - safeCap),
    over: safeCount > safeCap,
  };
}

function noteReadyFindTasksHeadingLine(text) {
  try {
    const lines = String(text === null || text === undefined ? "" : text).split(
      "\n",
    );
    let inFence = false;
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index];
      if (NOTE_READY_FENCE_RE.test(line)) {
        inFence = !inFence;
        continue;
      }
      if (inFence) {
        continue;
      }
      if (NOTE_READY_TASKS_HEADING_RE.test(line)) {
        return index;
      }
    }
    return -1;
  } catch (error) {
    return -1;
  }
}

function noteReadyHeadingChipModel(entry, options = {}) {
  try {
    const invalid = Boolean(options.invalid);
    const mobileDefault = Boolean(options.mobileDefault);
    if (!entry || typeof entry !== "object") {
      return {
        available: false,
        text: "ready –",
        tooltip: "ready count unavailable",
        aria: "ready count: unavailable",
        over: false,
        placeholder: true,
        exempt: false,
        key: "unavailable",
      };
    }
    const count = Number.isInteger(entry.count) ? entry.count : 0;
    const cap = Number.isInteger(entry.cap) ? entry.cap : null;
    const makeUp =
      entry.make_up && typeof entry.make_up === "object"
        ? entry.make_up
        : null;
    const remedies = NOTE_READY_REMEDIES;
    if (entry.state === "exempt") {
      const tooltip =
        `${count} ready-lane tasks · no cap (ready_cap: off) · ${remedies}` +
        (mobileDefault ? " · default cap on mobile" : "");
      return {
        available: true,
        text: `ready ${count} · no cap`,
        tooltip,
        aria: tooltip,
        over: false,
        placeholder: false,
        exempt: true,
        key: `exempt:${count}`,
      };
    }
    const capText = cap === null ? "–" : String(cap);
    const sourceLabel = noteReadyCapSourceLabel(entry.cap_source);
    let lane = "";
    if (makeUp) {
      const ready = Number.isInteger(makeUp.ready) ? makeUp.ready : 0;
      const fresh = Number.isInteger(makeUp.new) ? makeUp.new : 0;
      const rotten = Number.isInteger(makeUp.rotten) ? makeUp.rotten : 0;
      lane = `${count} ready-lane tasks = ${ready} ready + ${fresh} new + ${rotten} rotten`;
    } else {
      lane = `${count} ready-lane tasks`;
    }
    const overText =
      entry.state === "crowded" && Number.isInteger(entry.over_by)
        ? ` · ${entry.over_by} over`
        : "";
    let tooltip = `${lane} · cap ${capText} (${sourceLabel})${overText} · ${remedies}`;
    if (invalid) {
      tooltip += ` · ready_cap invalid, using ${capText}`;
    }
    if (mobileDefault) {
      tooltip += " · default cap on mobile";
    }
    if (entry.state === "crowded") {
      const text = `ready ${count}/${capText} · +${entry.over_by}`;
      return {
        available: true,
        text,
        tooltip,
        aria: tooltip,
        over: true,
        placeholder: false,
        exempt: false,
        key: `crowded:${count}/${capText}`,
      };
    }
    if (entry.state === "full") {
      const text = `ready ${count}/${capText} · full`;
      return {
        available: true,
        text,
        tooltip,
        aria: tooltip,
        over: false,
        placeholder: false,
        exempt: false,
        key: `full:${count}/${capText}`,
      };
    }
    const text = `ready ${count}/${capText}`;
    return {
      available: true,
      text,
      tooltip,
      aria: tooltip,
      over: false,
      placeholder: false,
      exempt: false,
      key: `${entry.state}:${count}/${capText}`,
    };
  } catch (error) {
    return {
      available: false,
      text: "ready –",
      tooltip: "ready count unavailable",
      aria: "ready count: unavailable",
      over: false,
      placeholder: true,
      exempt: false,
      key: "unavailable",
    };
  }
}

function noteReadyReadyNotesSummary(snapshot) {
  try {
    if (!snapshot || snapshot.available !== true) {
      return "CROWDED –";
    }
    const totals = snapshot.totals || {};
    const crowded = Number.isInteger(totals.crowded) ? totals.crowded : 0;
    if (crowded === 0) {
      return "CROWDED 0 ✓ · every note has room";
    }
    const full = Number.isInteger(totals.full) ? totals.full : 0;
    const excess = Number.isInteger(totals.excess) ? totals.excess : 0;
    const notes = Number.isInteger(totals.notes) ? totals.notes : 0;
    return `CROWDED ${crowded} · ${excess} over · ${full} full · ${notes} notes`;
  } catch (error) {
    return "CROWDED –";
  }
}

function noteReadyEscapeHtml(text) {
  return String(text === null || text === undefined ? "" : text).replace(
    /[&<>"']/g,
    (ch) => {
      if (ch === "&") {
        return "&amp;";
      }
      if (ch === "<") {
        return "&lt;";
      }
      if (ch === ">") {
        return "&gt;";
      }
      if (ch === '"') {
        return "&quot;";
      }
      return "&#39;";
    },
  );
}

// --- Plan block model -----------------------------------------------------

function planBlockTargetPath(app, sourcePath) {
  if (sourcePath && PLAN_DAILY_PATH_RE.test(String(sourcePath))) {
    return String(sourcePath);
  }
  return todayDailyPath(new Date(), getDailyNotesOptions(app));
}

function planBlockTasks(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const tasks = plugins && plugins[PLAN_TASKS_PLUGIN_ID];
    if (tasks && typeof tasks.getTasks === "function") {
      const all = tasks.getTasks();
      return Array.isArray(all) ? all : null;
    }
  } catch (error) {
    // The Tasks plugin is optional; the block shows `–` without it.
  }
  return null;
}

// Daily NEXT/PENDING presentation uses the dashboard section budget.
// A supplied budget (including unavailable nulls) is used as-is and
// never replaced with an ungated whole-lane fallback. Standalone
// callers without a prepared budget compute the same section through
// dashboardLaneBudgetFromTasks when Tasks data is present.
function unavailablePlanDashboardBudget(effective, lane) {
  return {
    section: null,
    lane: null,
    count: null,
    laneCount: null,
    cap: lane === "next" ? effective.maxNext : effective.maxPending,
    over: false,
    today: null,
  };
}

function resolvePlanDashboardBudget(
  supplied,
  taskList,
  day,
  effective,
  lane,
  isTodayPredicate,
  hasTasks,
) {
  if (supplied !== undefined) {
    if (!supplied || typeof supplied !== "object") {
      return unavailablePlanDashboardBudget(effective, lane);
    }
    return supplied;
  }
  if (!hasTasks) {
    return unavailablePlanDashboardBudget(effective, lane);
  }
  try {
    return dashboardLaneBudgetFromTasks(
      taskList,
      day,
      effective,
      lane,
      isTodayPredicate,
    );
  } catch (error) {
    return unavailablePlanDashboardBudget(effective, lane);
  }
}

// Synchronous view-model for the ```bob-plan block. Never throws: missing
// content, caps, or Tasks all degrade to `–` placeholders, never an error.
// `isToday` is the caller's Today predicate over cached Tasks tasks
// (the plugin passes its synchronous cache); it still feeds READY.
// READY is the shared live current backlog (Today excluded); it never
// changes what the ledger's PLAN status means.
// Daily NEXT/PENDING badges and their cap lints follow dashboard section
// counts. Whole-lane `next`/`pending` remain available to callers. Optional
// `nextDashboard` / `pendingDashboard` are guarded budgets from the paint path.
function planBlockModel({
  content,
  tasks,
  today,
  caps,
  sourcePath,
  app,
  isToday,
  isReviewBucket,
  review,
  nextDashboard,
  pendingDashboard,
  hueFor,
  themeConfigured,
  themeSimilarTo,
  taskLineForBlock,
  isOffClockLink,
}) {
  const effective = effectivePlanCaps(caps);
  const targetPath = planBlockTargetPath(app, sourcePath);
  let budget;
  try {
    budget = typeof content === "string" ? computePlanBudget(content, effective, targetPath, { isOffClockLink }) : emptyPlanBudget(effective);
  } catch (error) {
    budget = emptyPlanBudget(effective);
  }
  const hasTasks = Array.isArray(tasks);
  const isTodayPredicate =
    typeof isToday === "function" ? isToday : () => false;
  const taskList = hasTasks ? tasks : [];
  const day = today === undefined ? new Date() : today;
  let next;
  let pending;
  try {
    next = laneBudgetFromTasks(taskList, day, effective, "next");
  } catch (error) {
    next = { count: 0, cap: effective.maxNext, over: false };
  }
  try {
    pending = laneBudgetFromTasks(taskList, day, effective, "pending");
  } catch (error) {
    pending = { count: 0, cap: effective.maxPending, over: false };
  }
  const nextDash = resolvePlanDashboardBudget(
    nextDashboard,
    taskList,
    day,
    effective,
    "next",
    isTodayPredicate,
    hasTasks,
  );
  const pendingDash = resolvePlanDashboardBudget(
    pendingDashboard,
    taskList,
    day,
    effective,
    "pending",
    isTodayPredicate,
    hasTasks,
  );
  const nextModel = dashboardLaneBadgeModel(nextDash, "next");
  const pendingModel = dashboardLaneBadgeModel(pendingDash, "pending");
  let ready = null;
  if (hasTasks) {
    try {
      ready = readyBudgetFromTasks(
        taskList,
        day,
        effective,
        isTodayPredicate,
        isReviewBucket,
      );
    } catch (error) {
      ready = null;
    }
  }
  // Ledger PLAN status stays independent of lane pressure. READY over
  // still flags the aggregate `over` for existing READY tests; the
  // accessible summary uses the ledger status for "over plan".
  const over =
    budget.status === "over" || (hasTasks && ready && ready.over);
  const lintWarnings = budget.warnings.slice();
  lintWarnings.push(...pomodoroThemesPlanLintWarnings(budget.entries, themeConfigured, themeSimilarTo));
  if (nextModel.placeholder === false && nextModel.sectionOver) {
    lintWarnings.push({
      code: PLAN_LINT_NEXT_CAP,
      message: `NEXT has ${nextModel.section}/${nextModel.cap} tasks; release some with Alt+N`,
    });
  }
  if (pendingModel.placeholder === false && pendingModel.sectionOver) {
    lintWarnings.push({
      code: PLAN_LINT_PENDING_CAP,
      message: `PENDING has ${pendingModel.section}/${pendingModel.cap} tasks; release some with Alt+N`,
    });
  }
  if (
    hasTasks &&
    ready &&
    Number.isInteger(ready.count) &&
    ready.over
  ) {
    lintWarnings.push({
      code: PLAN_LINT_READY_CAP,
      message: `READY has ${ready.count}/${ready.cap} tasks; prune at the weekly review`,
    });
  }
  const themeCounts = budget.entries
    .filter((entry) => !entry.exempt)
    .map((entry) => `${entry.name} ${entry.links}`);
  // Total lane pressure for the gated READY tooltip: the gated
  // count plus the NEW and ROTTEN buckets behind it. Without a review
  // breakdown the badge keeps its legacy tooltip.
  const reviewLane =
    review &&
    Number.isInteger(review.new) &&
    review.new >= 0 &&
    Number.isInteger(review.rotten) &&
    review.rotten >= 0 &&
    ready &&
    Number.isInteger(ready.count) &&
    ready.count >= 0
      ? {
          total: review.new + review.rotten + ready.count,
          new: review.new,
          rotten: review.rotten,
          ready: ready.count,
        }
      : null;
  const readyModel = readyBadgeModel(
    ready
      ? { count: ready.count, cap: ready.cap, over: ready.over }
      : { count: null, cap: effective.maxReady },
    reviewLane ? { lane: reviewLane } : {},
  );
  let todayTone = null;
  try {
    todayTone = todayBadgeTone(budget);
  } catch (error) {
    todayTone = null;
  }
  const offClockCount = budget && budget.links && budget.links.offClock > 0 ? budget.links.offClock : 0;
  const planTitleText = [themeCounts.join(" · ") || null, offClockCount > 0 ? `${offClockCount} off-clock uncapped` : null].filter(Boolean).join(" · ");
  return {
    targetPath,
    hasContent: typeof content === "string",
    hasTasks,
    planText: budget.hasSection
      ? `TODAY ${budget.links.count}/${budget.links.cap}`
      : "TODAY –",
    todayTone,
    planTitle: budget.hasSection
      ? planTitleText || "no themes"
      : "no Pomodoros section",
    nextText: nextModel.text,
    pendingText: pendingModel.text,
    readyText: hasTasks ? readyModel.text : "READY –",
    readyModel,
    nextModel,
    pendingModel,
    themesText:
      budget.themeNames.length > 0
        ? `★ ${budget.themeNames.join(" · ")}`
        : "",
    // Per-component pill models for the ★ theme line. Computed only
    // when the caller supplies `hueFor` (the plan block paint does);
    // otherwise the text fallback above carries the names.
    themePills: (() => {
      try {
        if (typeof hueFor !== "function" || budget.themeNames.length === 0) {
          return [];
        }
        const pills = [];
        for (const themeName of budget.themeNames) {
          const parts = pomodoroThemePillModels(themeName, hueFor);
          if (parts.length > 0) {
            pills.push({ name: themeName, parts });
          }
        }
        return pills;
      } catch (error) {
        return [];
      }
    })(),
    lints: lintWarnings.map((warning) =>
      warning.line === undefined || warning.line === null
        ? `${warning.message}  ${warning.code}`
        : `${warning.message} (line ${warning.line})  ${warning.code}`,
    ),
    over,
    budget,
    next,
    pending,
    nextDashboard: nextDash,
    pendingDashboard: pendingDash,
    ready,
    lane: reviewLane,
    todayRoots: planBlockTodayRoots(budget, content, targetPath, app, hasTasks ? taskList : null, taskLineForBlock),
  };
}

